            let has_n2 = b.cmp_lt_i32(it_p2, cx.nkv);
            let nkv_m1c = b.add_i32(cx.nkv, cm1);
            let nn2 = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(has_n2), a: Opnd::Val(it_p2), b: Opnd::Val(nkv_m1c) });
