            let j128 = b.shl_i32(cx.j, c7e);
            let jbase = b.add_i32(lbase, j128);
            let half8 = b.shl_i32(half, c3e); // 8 bytes per lane half
            // write address of chunk (4 e' + q) of this lane's row: (chunk ^ (j & 7)) * 16 + 8 half
