/// `_vs6` (gen6): `_vs128` with the K ring one tile ahead - QK(t+1) runs in the V window of tile t, K(t+2) is staged at V(t) and waited at the end of M(t); PV stays in M.
/// Role selector of the vendor-structure kernels: `_vs6` has its own role (K-ahead ring), every other `_vs128`-family kernel the `_vs128` role.
fn vs_role_fn(name: &str) -> fn(&mut FnBuilder, &FmhaTCtx, bool) {
    if name.ends_with("_vs6") { emit_fmha_vs6_role } else if name.ends_with("_vs9") { emit_fmha_vs9_role } else { emit_fmha_vs128_role }
}

/// `_vs9` (gen9): the vendor-mirror rewrite, scaffolded as a copy of `_vs128` (see `emit_fmha_vs9_role`).
pub fn fmha_fwd_hd128_mxfp8_vs9() -> Function {
    VS_MODE.store(true, std::sync::atomic::Ordering::SeqCst);
    let f = fmha_t_build("fmha_fwd_hd128_mxfp8_vs9", false, true);
    VS_MODE.store(false, std::sync::atomic::Ordering::SeqCst);
    f
}

pub fn fmha_fwd_hd128_mxfp8_vs6() -> Function {
    VS_MODE.store(true, std::sync::atomic::Ordering::SeqCst);
    let f = fmha_t_build("fmha_fwd_hd128_mxfp8_vs6", false, true);
    VS_MODE.store(false, std::sync::atomic::Ordering::SeqCst);
    f
}

pub fn fmha_fwd_hd128_mxfp8_vs5() -> Function {
    VS_MODE.store(true, std::sync::atomic::Ordering::SeqCst);
    VS5_BUILD.store(true, std::sync::atomic::Ordering::SeqCst);
    let f = fmha_t_build("fmha_fwd_hd128_mxfp8_vs5", false, true);
    VS5_BUILD.store(false, std::sync::atomic::Ordering::SeqCst);
    VS_MODE.store(false, std::sync::atomic::Ordering::SeqCst);
    f
}

/// `_vs5` only: `FMHA_OPT=winc` (Block C: PV + row sums as a pinned safe-asm block), `wina` (Block A), `winb` (Block B, the QK-under-VALU overlap); see docs/archive/gen5-window-spec.md.
/// Each block is gated separately (md5 + 15 shapes + determinism + timing). `wina` / `winb` are not wired yet and stop the build with a message.
fn vs5_win(name: &str) -> bool {
    let want = fmha_t_opt(name) && VS5_BUILD.load(std::sync::atomic::Ordering::SeqCst);
    if want && name != "winc" && name != "winm" {
        panic!("FMHA_OPT={name}: this safe-asm window block is not wired yet (docs/archive/gen5-window-spec.md section 7)");
    }
    want
}/// 8-elements-per-thread fp16-partial combine (`..._kvsplit_combine8h`): grid = ceil(rows_total * 128 / 8 / 256); one 16-byte load per split, one 16-byte store.
pub fn fmha_fwd_hd128_mxfp8_kvsplit_combine8h() -> Function {
    let mut b = FnBuilder::new("fmha_fwd_hd128_mxfp8_kvsplit_combine8h", 256);
    b.arg("ptr_ohat", DType::Ptr, 0x00, 8); b.arg("ptr_lse", DType::Ptr, 0x08, 8); b.arg("ptr_out", DType::Ptr, 0x10, 8);
    b.arg("rows_total", DType::I32, 0x18, 4); b.arg("d", DType::I32, 0x1C, 4); b.arg("splits", DType::I32, 0x20, 4);
    combine_contract(&mut b);
    let ohat = b.let_(Op::KernargPtr { offset: 0x00 });
    let lse = b.let_(Op::KernargPtr { offset: 0x08 });
    let out = b.let_(Op::KernargPtr { offset: 0x10 });
    let rows = b.let_(Op::KernargI32 { offset: 0x18 });
    let splits = b.let_(Op::KernargI32 { offset: 0x20 });
    let tid = b.let_(Op::WorkitemId);
    let bx = b.let_(Op::WorkgroupIdX);
    let c0 = b.c_i32(0); let c2 = b.c_i32(2); let c4 = b.c_i32(4); let c16 = b.c_i32(16); let c8 = b.c_i32(8); let cm1 = b.c_i32(-1);
    let bx256 = b.shl_i32(bx, c8);
    let t_raw = b.add_i32(bx256, tid);
    let total8 = b.shl_i32(rows, c4); // rows * 128 / 8
    let last = b.add_i32(total8, cm1);
    let ok = b.cmp_lt_i32(t_raw, total8);
    let t8 = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(ok), a: Opnd::Val(t_raw), b: Opnd::Val(last) });
    let row = b.let_(Op::LshrI32(Opnd::Val(t8), Opnd::Val(c4)));
    // t8 <= rows * 16 - 1 (clamped), so row = t8 >> 4 <= rows - 1 (the interval engine keeps the rational upper bound of a shift)
    b.assume_trusted(row, Ext::c(0), Ext::ka(0x18) - Ext::c(1), "row = clamped thread index >> k <= rows - 1: the engine keeps the rational upper bound of a shift");
    let neg_big = b.c_f32(-1.0e30); let neg_big_i = b.bitcast_i32(neg_big);
    let zero_f = b.c_f32(0.0); let zero_i = b.bitcast_i32(zero_f);
    let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0)), (DType::I32, Opnd::Val(neg_big_i))];
    for _ in 0..9 { inits.push((DType::I32, Opnd::Val(zero_i))); }
    let vars = b.begin_loop(&inits);
    // host contract: the split counter runs 0 .. splits - 1 inside the body (the loop exits at splits; the step s + 1 <= splits is TRUSTED)
    b.assume_trusted(vars[0], Ext::c(0), Ext::ka(0x20) - Ext::c(1), "split counter: starts at 0 and the loop exits when s + 1 >= splits (sched_end_loop), so the body only runs with s <= splits - 1");
    let rs = b.mul_i32(vars[0], rows);
    let lrow = b.add_i32(rs, row);
    let lse_off = b.shl_i32(lrow, c2);
    let lp = b.ptr_add(lse, lse_off);
    let l = b.load_f32(lp, 0);
    let rs16 = b.shl_i32(rs, c4);
    let oidx = b.add_i32(rs16, t8);
    let o_off = b.shl_i32(oidx, c4); // 16 bytes per thread
    let op = b.ptr_add(ohat, o_off);
    let ov = b.load_b128(op, 0);
    let m_old = b.bitcast_f32(vars[1]);
    let den = b.bitcast_f32(vars[2]);
    let m_new = b.max_f32(m_old, l);
    let neg1 = b.c_f32(-1.0);
    let dm = b.mul_f32(m_new, neg1);
    let d_old = b.add_f32(m_old, dm);
    let d_new = b.add_f32(l, dm);
    let a = b.exp2_f32(d_old);
    let w = b.exp2_f32(d_new);
    let den_s = b.mul_f32(den, a);
    let den_n = b.add_f32(den_s, w);
    let m_i = b.bitcast_i32(m_new);
    let den_i = b.bitcast_i32(den_n);
    b.set_var(vars[1], m_i);
    b.set_var(vars[2], den_i);
    for wi in 0..4usize {
        let wd = b.frag4_lane(ov, wi as u8);
        let hs = b.let_(Op::LshrI32(Opnd::Val(wd), Opnd::Val(c16)));
        let lo = b.let_(Op::CvtF16ToF32(Opnd::Val(wd)));
        let hi = b.let_(Op::CvtF16ToF32(Opnd::Val(hs)));
        for (k, vv) in [(2 * wi, lo), (2 * wi + 1, hi)] {
            let acc = b.bitcast_f32(vars[3 + k]);
            let acc_s = b.mul_f32(acc, a);
            let wv = b.mul_f32(w, vv);
            let acc_n = b.add_f32(acc_s, wv);
            let acc_i = b.bitcast_i32(acc_n);
            b.set_var(vars[3 + k], acc_i);
        }
    }
    sched_end_loop(&mut b, vars[0], splits);
    let denf = b.bitcast_f32(Opnd::Var(vars[2]));
    let rd = b.rcp_f32(denf);
    let mut res: Vec<ValueId> = Vec::new();
    for k in 0..8usize { let accf = b.bitcast_f32(Opnd::Var(vars[3 + k])); res.push(b.mul_f32(accf, rd)); }
    let mut ow: Vec<ValueId> = Vec::new();
    for k in 0..4usize { ow.push(b.cvt_pk_bf16_f32(res[2 * k], res[2 * k + 1])); }
    let f4 = b.frag4(ow[0], ow[1], ow[2], ow[3]);
    let o_byte = b.shl_i32(t8, c4);
    let optr = b.ptr_add(out, o_byte);
    b.store_f32x4(optr, 0, f4);
    b.finish()
}

/// 16-elements-per-thread fp16-partial combine (`..._kvsplit_combine16h`): grid = ceil(rows_total * 128 / 16 / 256); two 16-byte loads per split, two 16-byte stores.
pub fn fmha_fwd_hd128_mxfp8_kvsplit_combine16h() -> Function {
    let mut b = FnBuilder::new("fmha_fwd_hd128_mxfp8_kvsplit_combine16h", 256);
    b.arg("ptr_ohat", DType::Ptr, 0x00, 8); b.arg("ptr_lse", DType::Ptr, 0x08, 8); b.arg("ptr_out", DType::Ptr, 0x10, 8);
    b.arg("rows_total", DType::I32, 0x18, 4); b.arg("d", DType::I32, 0x1C, 4); b.arg("splits", DType::I32, 0x20, 4);
    combine_contract(&mut b);
    let ohat = b.let_(Op::KernargPtr { offset: 0x00 });
    let lse = b.let_(Op::KernargPtr { offset: 0x08 });
    let out = b.let_(Op::KernargPtr { offset: 0x10 });
    let rows = b.let_(Op::KernargI32 { offset: 0x18 });
    let splits = b.let_(Op::KernargI32 { offset: 0x20 });
    let tid = b.let_(Op::WorkitemId);
    let bx = b.let_(Op::WorkgroupIdX);
    let c0 = b.c_i32(0); let c2 = b.c_i32(2); let c4 = b.c_i32(4); let c16 = b.c_i32(16); let c8 = b.c_i32(8); let cm1 = b.c_i32(-1);
    let bx256 = b.shl_i32(bx, c8);
    let t_raw = b.add_i32(bx256, tid);
    let c3 = b.c_i32(3); let c5 = b.c_i32(5);
    let total8 = b.shl_i32(rows, c3); // rows * 128 / 16
    let last = b.add_i32(total8, cm1);
    let ok = b.cmp_lt_i32(t_raw, total8);
    let t8 = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(ok), a: Opnd::Val(t_raw), b: Opnd::Val(last) });
    let row = b.let_(Op::LshrI32(Opnd::Val(t8), Opnd::Val(c3)));
    // the clamped thread index is <= rows * (elements per row / elements per thread) - 1, so row <= rows - 1 (the interval engine keeps the rational upper bound of a shift)
    b.assume_trusted(row, Ext::c(0), Ext::ka(0x18) - Ext::c(1), "row = clamped thread index >> k <= rows - 1: the engine keeps the rational upper bound of a shift");
    let neg_big = b.c_f32(-1.0e30); let neg_big_i = b.bitcast_i32(neg_big);
    let zero_f = b.c_f32(0.0); let zero_i = b.bitcast_i32(zero_f);
    let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0)), (DType::I32, Opnd::Val(neg_big_i))];
    for _ in 0..17 { inits.push((DType::I32, Opnd::Val(zero_i))); }
    let vars = b.begin_loop(&inits);
    // host contract: the split counter runs 0 .. splits - 1 inside the body (the loop exits at splits; the step s + 1 <= splits is TRUSTED)
    b.assume_trusted(vars[0], Ext::c(0), Ext::ka(0x20) - Ext::c(1), "split counter: starts at 0 and the loop exits when s + 1 >= splits (sched_end_loop), so the body only runs with s <= splits - 1");
    let rs = b.mul_i32(vars[0], rows);
    let lrow = b.add_i32(rs, row);
    let lse_off = b.shl_i32(lrow, c2);
    let lp = b.ptr_add(lse, lse_off);
    let l = b.load_f32(lp, 0);
    let rs8 = b.shl_i32(rs, c3);
    let oidx = b.add_i32(rs8, t8);
    let o_off = b.shl_i32(oidx, c5); // 32 bytes per thread
    let op = b.ptr_add(ohat, o_off);
    let ov0 = b.load_b128(op, 0);
    let ov1 = b.load_b128(op, 16);
    let m_old = b.bitcast_f32(vars[1]);
    let den = b.bitcast_f32(vars[2]);
    let m_new = b.max_f32(m_old, l);
    let neg1 = b.c_f32(-1.0);
    let dm = b.mul_f32(m_new, neg1);
    let d_old = b.add_f32(m_old, dm);
    let d_new = b.add_f32(l, dm);
    let a = b.exp2_f32(d_old);
    let w = b.exp2_f32(d_new);
    let den_s = b.mul_f32(den, a);
    let den_n = b.add_f32(den_s, w);
    let m_i = b.bitcast_i32(m_new);
    let den_i = b.bitcast_i32(den_n);
    b.set_var(vars[1], m_i);
    b.set_var(vars[2], den_i);
    for wi in 0..8usize {
        let wd = if wi < 4 { b.frag4_lane(ov0, wi as u8) } else { b.frag4_lane(ov1, (wi - 4) as u8) };
        let hs = b.let_(Op::LshrI32(Opnd::Val(wd), Opnd::Val(c16)));
        let lo = b.let_(Op::CvtF16ToF32(Opnd::Val(wd)));
        let hi = b.let_(Op::CvtF16ToF32(Opnd::Val(hs)));
        for (k, vv) in [(2 * wi, lo), (2 * wi + 1, hi)] {
            let acc = b.bitcast_f32(vars[3 + k]);
            let acc_s = b.mul_f32(acc, a);
            let wv = b.mul_f32(w, vv);
            let acc_n = b.add_f32(acc_s, wv);
            let acc_i = b.bitcast_i32(acc_n);
            b.set_var(vars[3 + k], acc_i);
        }
    }
    sched_end_loop(&mut b, vars[0], splits);
    let denf = b.bitcast_f32(Opnd::Var(vars[2]));
    let rd = b.rcp_f32(denf);
    let mut res: Vec<ValueId> = Vec::new();
    for k in 0..16usize { let accf = b.bitcast_f32(Opnd::Var(vars[3 + k])); res.push(b.mul_f32(accf, rd)); }
    let mut ow: Vec<ValueId> = Vec::new();
    for k in 0..8usize { ow.push(b.cvt_pk_bf16_f32(res[2 * k], res[2 * k + 1])); }
    let f4a = b.frag4(ow[0], ow[1], ow[2], ow[3]);
    let f4b = b.frag4(ow[4], ow[5], ow[6], ow[7]);
    let o_byte = b.shl_i32(t8, c5);
    let optr = b.ptr_add(out, o_byte);
    b.store_f32x4(optr, 0, f4a);
    b.store_f32x4(optr, 16, f4b);
    b.finish()
}

pub fn fmha_fwd_hd128_mxfp8_vs128() -> Function {
    VS_MODE.store(true, std::sync::atomic::Ordering::SeqCst);
    let f = fmha_t_build("fmha_fwd_hd128_mxfp8_vs128", false, true);
    VS_MODE.store(false, std::sync::atomic::Ordering::SeqCst);
    f
}

pub fn fmha_fwd_hd128_mxfp8_vs() -> Function {
    VS_MODE.store(true, std::sync::atomic::Ordering::SeqCst);
    let f = fmha_t_build("fmha_fwd_hd128_mxfp8_vs", false, true);
    VS_MODE.store(false, std::sync::atomic::Ordering::SeqCst);
    f
}
pub fn fmha_fwd_hd128_mxfp8_t() -> Function {
    fmha_t_build("fmha_fwd_hd128_mxfp8_t", false, false)
}

/// Phase-shifted ping-pong variant (see `emit_fmha_pp_role`): same ABI and numerics.
pub fn fmha_fwd_hd128_mxfp8_pp() -> Function {
    fmha_t_build("fmha_fwd_hd128_mxfp8_pp", true, false)
}

/// Vendor-style softmax variant (Schraudolph exp2 through `v_cvt_pknorm_u16_f32`, see `emit_fmha_sv_role`).
pub fn fmha_fwd_hd128_mxfp8_sv() -> Function {
    fmha_t_build("fmha_fwd_hd128_mxfp8_sv", false, true)
}

/// GPU-semantics host contract of the 656-byte FMHA kernarg ABI (docs/gpu-semantics-verifier.md): exactly the allocations `tests/gpu/ref_host.cpp` passes.
/// Annotation only: it emits no code. B (batch) = `grid_z` for the single-kernel paths; the KV-split kernel launches `grid_z = B * splits`.
///   Q  (0x010): B * S*H*D bytes                = grid_z * ka(0x0A0)            K, V (0x020, 0x030): B * SK*HK*D = grid_z * ka(0x0E0) / ka(0x170)
///   O  (0x000): B * S*H*D*2 bytes (bf16)       = grid_z * ka(0x1A0)
///   Q scale (0x200): B * S*H*4 logical + 512*H*4 zeroed slack;  K scale (0x210): B * SK*HK*4 logical + 640*H*4 zeroed slack;  V scale (0x220): 4096 bytes
///   KV-split: Ohat (0x270) = splits * rows_total * 128 * 4 (fp32-sized allocation), lse (0x278) = splits * rows_total * 4
/// LDS tile protocol of the vendor-structure kernels (`_vs128`, `_kvsplit`, `_vs5`; docs/gpu-semantics-verifier.md 3.1). Layout (bytes): 2-slot ring, slot k = [32768 k, +32768) with the K tile in its first 16 KB
/// and the V tile in its second 16 KB; K-scale ring [65536 + 512 k, +512); ones block 67584 (2 KB); Q b1 staging 69632 (16 KB); Q b0 staging 86016 (16 KB). Tile t lives in slot t & 1 with version t:
/// group A stages K(t+1) and its scales at the start of the V phase of tile t, group B stages V(t+1); both wait for their DMA (`wait_vm(0)`) at the end of the V phase and the barrier that follows
/// publishes them; the M phase of tile t reads V(t) and K(t+1); the second barrier of the iteration keeps the next DMA (which reuses the slot of tile t) behind the last read of tile t.
fn fmha_vs_tiles(b: &mut FnBuilder) {
    b.lds_ring("K", 0, 32768, 2);
    b.lds_ring("V", 16384, 32768, 2);
    b.lds_ring("KD", 65536, 512, 2);
    b.lds_tile("ones", 67584, 2048);
    b.lds_tile("Q1", 69632, 16384);
    b.lds_tile("Q0", 86016, 16384);
    // epilogue: every wave transposes through its own 4 KB scratch (8 x 4096 from the Q staging base, which is dead after the loop and a barrier): private to the wave, written and read back by it
    b.lds_private("epi", 69632, 4096, 8);
    b.lds_alias("epi", "Q1");
    b.lds_alias("epi", "Q0");
    b.lds_alias("epi", "V");
    // the K and V rings share the 2 x 32 KB window (disjoint halves of every slot) and the V ring's declared extent also covers the small regions behind it
    b.lds_alias("K", "V");
    b.lds_alias("V", "KD");
    b.lds_alias("V", "ones");
    b.lds_alias("V", "Q1");
}

fn fmha_abi_contract(b: &mut FnBuilder, is_kvs: bool, rows_per_block: i64) {
    // host contract on the scalars the proofs need (the shapes are positive; the vendor ABI carries D = 128 in every stride)
    for off in [0x060u32, 0x110] {
        b.ka_range(off, 1, i64::MAX);
    }
    // Shape relations of the vendor ABI (BSHD tensors, head dim 128; the strides are BYTES) - every line is what tests/gpu/ref_host.cpp (and the aiter caller) passes:
    //   Q seq stride 0x70 = H*128, head stride 0x90 = 128, batch stride 0xA0 = S*(H*128);   K seq stride 0xC0 = HK*128, head stride 0xD0 = 128, batch stride 0xE0 = SK*(HK*128)
    //   V strides 0x150/0x160/0x170 = the K strides;   O seq stride 0x180 = H*256, head stride 0x190 = 256, batch stride 0x1A0 = S*(H*256)
    //   Q descale: batch 0x230 = S*H*4, head 0x240 = 4;   K descale: batch 0x250 = SK*HK*4, head 0x260 = 4
    //   GQA: H = HK * gqa with gqa a power of two <= 16 (the kernels use kv_head = head >> log2(gqa));   launch grid y = H, grid x = ceil(S / rows_per_block)
    let hk = Ext::sym("HK");
    b.ka_range(0x0B0, 1, 16);
    b.ka_is(0x140, hk.clone() * Ext::ka(0x0B0));
    b.grid_is(1, Ext::ka(0x140));
    b.grid_is(0, Ext::ka(0x060).ceil_div(rows_per_block));
    b.ka_range(0x090, 128, 128);
    b.ka_range(0x0D0, 128, 128);
    b.ka_range(0x160, 128, 128);
    b.ka_range(0x190, 256, 256);
    b.ka_range(0x240, 4, 4);
    b.ka_range(0x260, 4, 4);
    b.ka_is(0x070, Ext::ka(0x140) * Ext::c(128));
    b.ka_is(0x0A0, Ext::ka(0x060) * Ext::ka(0x070));
    b.ka_is(0x0C0, hk.clone() * Ext::c(128));
    b.ka_is(0x0E0, Ext::ka(0x110) * Ext::ka(0x0C0));
    b.ka_is(0x150, Ext::ka(0x0C0));
    b.ka_is(0x170, Ext::ka(0x0E0));
    b.ka_is(0x180, Ext::ka(0x140) * Ext::c(256));
    b.ka_is(0x1A0, Ext::ka(0x060) * Ext::ka(0x180));
    b.ka_is(0x230, Ext::ka(0x060) * Ext::ka(0x140) * Ext::c(4));
    b.ka_is(0x250, Ext::ka(0x110) * hk * Ext::c(4));
    let h = Ext::ka(0x140);
    // batch count: the grid z axis for the single-kernel paths, grid z / splits for the KV-split launch (grid z = B * splits + split)
    let batch = if is_kvs {
        b.ka_range(0x280, 1, i64::MAX);
        b.ka_range(0x284, 1, i64::MAX);
        let bsym = Ext::sym("B");
        b.grid_is(2, bsym.clone() * Ext::ka(0x280));
        // rows_total = B * S * H (the per-split stride of the partial buffers; ref_host: `rows_total = B*S*H`)
        b.ka_is(0x284, bsym.clone() * Ext::ka(0x060) * Ext::ka(0x140));
        let splits = Ext::ka(0x280);
        let rows_total = Ext::ka(0x284);
        b.arg_tensor("ptr_ohat", splits.clone() * rows_total.clone() * Ext::c(128 * 4));
        b.arg_tensor("ptr_lse", splits * rows_total * Ext::c(4));
        bsym
    } else {
        Ext::grid_z()
    };
    b.arg_tensor("ptr_q", batch.clone() * Ext::ka(0x0A0));
    b.arg_tensor("ptr_k", batch.clone() * Ext::ka(0x0E0));
    b.arg_tensor("ptr_v", batch.clone() * Ext::ka(0x170));
    b.arg_tensor("ptr_o", batch.clone() * Ext::ka(0x1A0));
    let qs = batch.clone() * Ext::ka(0x230);
    b.arg_tensor_slack("ptr_q_descale", qs.clone(), qs + Ext::c(512 * 4) * h.clone());
    let ks = batch * Ext::ka(0x250);
    b.arg_tensor_slack("ptr_k_descale", ks.clone(), ks + Ext::c(640 * 4) * h);
    b.arg_tensor("ptr_v_descale", Ext::c(4096));
}

/// Host contract of the five `fmha_fwd_hd128_mxfp8_kvsplit_combine*` kernels (kernarg: ohat@0, lse@8, out@0x10, rows_total@0x18, d@0x1C, splits@0x20):
/// Ohat = splits * rows_total * 128 * 4 (the host allocation is fp32-sized so fp16 and fp32 partials fit), lse = splits * rows_total * 4, out = rows_total * 128 * 2 (bf16).
fn combine_contract(b: &mut FnBuilder) {
    b.ka_range(0x18, 1, i64::MAX);
    b.ka_range(0x1C, 128, 128);
    b.ka_range(0x20, 1, i64::MAX);
    let rows = Ext::ka(0x18);
    let splits = Ext::ka(0x20);
    b.arg_tensor("ptr_ohat", splits.clone() * rows.clone() * Ext::c(128 * 4));
    b.arg_tensor("ptr_lse", splits * rows.clone() * Ext::c(4));
    b.arg_tensor("ptr_out", rows * Ext::c(128 * 2));
}
fn fmha_t_build(name: &str, pp: bool, sv: bool) -> Function {
    let mut b = FnBuilder::new(name, if name.ends_with("_t128") { 256 } else { 512 });
    let nbuf = if VS_MODE.load(std::sync::atomic::Ordering::SeqCst) { if (name.ends_with("_vs128") || name.ends_with("_vs5") || name.ends_with("_vs6") || name.ends_with("_vs9")) || name.ends_with("_kvsplit") { 2 } else { 3 } } else if fmha_t_opt("dbuf") { 2 } else { 1 };
    if pp {
        b.lds((512 * fmha_t_pitch() + 2048) as u32);
    } else {
        let pad: i32 = std::env::var("FMHA_LDSPAD").ok().and_then(|v| v.parse().ok()).unwrap_or(0);
        let cb = if fmha_t_opt("dma") && !vs_active() { 33280 } else { 256 * fmha_t_pitch() };
        // vendor-structure kernels: + a 2 KB block of E4M3 ones and 16 KB for the per-wave second Q fragment (vs128)
        if vs_active() {
            b.lds(if (name.ends_with("_vs128") || name.ends_with("_vs5") || name.ends_with("_vs6") || name.ends_with("_vs9")) || name.ends_with("_kvsplit") { VS128_LDS_BYTES + if fmha_t_opt("epreloc") { 32768 } else { 0 } } else if name.ends_with("_g3o") { 4 * 32768 + 2048 } else if name.ends_with("_vsm") || name.ends_with("_g2") || name.ends_with("_g3") || name.ends_with("_t128") { 3 * 32768 + 2048 + 2048 + 16384 + 16384 } else { VS_LDS_BYTES } + pad as u32);
        } else {
            // the swz K-scale scratch (kdlds path of the `_t` role) writes the odd thread's dword 1152 B above its row slot: rows up to 127, 2 parities of 512 B: the last dword ends 128 B beyond the
            // historical 2048 + 1024 + 1024 tail (a benign over-write that the hardware drops; found by gpu_verify GV-LDS-OOB). The declared segment now covers it.
            let kd_scratch_tail: i32 = if fmha_t_opt("swz") && !fmha_t_opt("dma") { 128 } else { 0 };
            b.lds((nbuf * cb + 2048 + 1024 + 1024 + pad + kd_scratch_tail) as u32);
        }
    }
    b.arg("ptr_o", DType::Ptr, 0x000, 8);
    b.arg("ptr_q", DType::Ptr, 0x010, 8);
    b.arg("ptr_k", DType::Ptr, 0x020, 8);
    b.arg("ptr_v", DType::Ptr, 0x030, 8);
    b.arg("s_seq_len", DType::I32, 0x060, 4);
    b.arg("s_Seqs", DType::I32, 0x070, 4);
    b.arg("s_Hs", DType::I32, 0x090, 4);
    b.arg("s_Bs", DType::I32, 0x0A0, 4);
    b.arg("s_gqa", DType::I32, 0x0B0, 4);
    b.arg("s_k_Seqs", DType::I32, 0x0C0, 4);
    b.arg("s_k_Hs", DType::I32, 0x0D0, 4);
    b.arg("s_k_Bs", DType::I32, 0x0E0, 4);
    b.arg("s_kv_seq_len", DType::I32, 0x110, 4);
    b.arg("s_q_head_num", DType::I32, 0x140, 4);
    b.arg("s_v_Seqs", DType::I32, 0x150, 4);
    b.arg("s_v_Hs", DType::I32, 0x160, 4);
    b.arg("s_v_Bs", DType::I32, 0x170, 4);
    b.arg("s_o_Seqs", DType::I32, 0x180, 4);
    b.arg("s_o_Hs", DType::I32, 0x190, 4);
    b.arg("s_o_Bs", DType::I32, 0x1A0, 4);
    b.arg("ptr_q_descale", DType::Ptr, 0x200, 8);
    b.arg("ptr_k_descale", DType::Ptr, 0x210, 8);
    b.arg("ptr_v_descale", DType::Ptr, 0x220, 8);
    b.arg("s_descale_q_Bs", DType::I32, 0x230, 4);
    b.arg("s_descale_q_Hs", DType::I32, 0x240, 4);
    b.arg("s_descale_k_Bs", DType::I32, 0x250, 4);
    b.arg("s_descale_k_Hs", DType::I32, 0x260, 4);
    let is_kvs = name.ends_with("_kvsplit");
    if is_kvs {
        // KV-split kernel: the 656-byte base ABI plus the partial buffers and the split count (docs/archive/kvsplit-design.md; harness contract of kernel-occ)
        b.arg("ptr_ohat", DType::Ptr, 0x270, 8);
        b.arg("ptr_lse", DType::Ptr, 0x278, 8);
        b.arg("kvs_splits", DType::I32, 0x280, 4);
        b.arg("kvs_rows_total", DType::I32, 0x284, 4);
        if fmha_t_opt("fused") {
            b.arg("kvs_counters", DType::Ptr, 0x288, 8);
            b.arg("kvs_dummy_off", DType::I32, 0x290, 4);
        }
    } else {
        b.arg("abi_tail", DType::I32, 0x280, 16);
    }
    fmha_abi_contract(&mut b, is_kvs, if name.ends_with("_t128") { 128 } else { 256 });
    if name.ends_with("_vs128") || name.ends_with("_kvsplit") || name.ends_with("_vs5") {
        fmha_vs_tiles(&mut b);
    }

    let ptr_o = b.let_(Op::KernargPtr { offset: 0x000 });
    let ptr_q = b.let_(Op::KernargPtr { offset: 0x010 });
    let ptr_k = b.let_(Op::KernargPtr { offset: 0x020 });
    let ptr_v = b.let_(Op::KernargPtr { offset: 0x030 });
    let s_len = b.let_(Op::KernargI32 { offset: 0x060 });
    let gqa = b.let_(Op::KernargI32 { offset: 0x0B0 });
    let q_seqs = b.let_(Op::KernargI32 { offset: 0x070 });
    let q_hs = b.let_(Op::KernargI32 { offset: 0x090 });
    let q_bs = b.let_(Op::KernargI32 { offset: 0x0A0 });
    let k_seqs = b.let_(Op::KernargI32 { offset: 0x0C0 });
    let k_hs = b.let_(Op::KernargI32 { offset: 0x0D0 });
    let k_bs = b.let_(Op::KernargI32 { offset: 0x0E0 });
    let kv_len = b.let_(Op::KernargI32 { offset: 0x110 });
    let v_seqs = b.let_(Op::KernargI32 { offset: 0x150 });
    let v_hs = b.let_(Op::KernargI32 { offset: 0x160 });
    let v_bs = b.let_(Op::KernargI32 { offset: 0x170 });
    let o_seqs = b.let_(Op::KernargI32 { offset: 0x180 });
    let o_hs = b.let_(Op::KernargI32 { offset: 0x190 });
    let o_bs = b.let_(Op::KernargI32 { offset: 0x1A0 });
    let ptr_qd = b.let_(Op::KernargPtr { offset: 0x200 });
    let ptr_kd = b.let_(Op::KernargPtr { offset: 0x210 });
    let ptr_vd = b.let_(Op::KernargPtr { offset: 0x220 });
    let dq_bs = b.let_(Op::KernargI32 { offset: 0x230 });
    let dq_hs = b.let_(Op::KernargI32 { offset: 0x240 });
    let dk_bs = b.let_(Op::KernargI32 { offset: 0x250 });
    let dk_hs = b.let_(Op::KernargI32 { offset: 0x260 });

    let tid_full = b.let_(Op::WorkitemId);
    let qtile = b.let_(Op::WorkgroupIdX);
    let hidx = b.let_(Op::WorkgroupIdY);
    let zz = b.let_(Op::WorkgroupIdZ);
    // KV split: grid z = b * splits + split (splits in {2, 4, 8}: log2 = (s >> 1) - (s >> 3))
    let (bidx, kvs_split, kvs_lg) = if is_kvs {
        let spl = b.let_(Op::KernargI32 { offset: 0x280 });
        let ck1 = b.c_i32(1);
        let ck3 = b.c_i32(3);
        let cn1 = b.c_i32(-1);
        let s_h = b.let_(Op::LshrI32(Opnd::Val(spl), Opnd::Val(ck1)));
        let s_e = b.let_(Op::LshrI32(Opnd::Val(spl), Opnd::Val(ck3)));
        let s_en = b.mul_i32(s_e, cn1);
        let lg = b.add_i32(s_h, s_en);
        let bi = b.let_(Op::LshrI32(Opnd::Val(zz), Opnd::Val(lg)));
        let one_l = b.shl_i32(ck1, lg);
        let msk = b.add_i32(one_l, cn1);
        let sp = b.let_(Op::AndI32(Opnd::Val(zz), Opnd::Val(msk)));
        // host contract: grid z = B * splits with splits a power of two in {2, 4, 8}: bi = z >> log2(splits) in [0, B-1], sp = z & (splits-1) in [0, splits-1]
        b.assume_trusted(bi, Ext::c(0), Ext::sym("B") - Ext::c(1), "batch = grid_z >> log2(splits) with grid_z = B * splits (grid_is): variable shift, no interval rule");
        b.assume_trusted(sp, Ext::c(0), Ext::ka(0x280) - Ext::c(1), "split index = grid_z & (splits - 1), splits a power of two: and with a variable mask");
        (bi, Some(sp), Some(lg))
    } else {
        (zz, None, None)
    };

    let c1 = b.c_i32(1);
    let c2 = b.c_i32(2);
    let c3 = b.c_i32(3);
    let c4 = b.c_i32(4);
    let c5 = b.c_i32(5);
    let c6 = b.c_i32(6);
    let c7 = b.c_i32(7);
    let c8 = b.c_i32(8);
    let c15 = b.c_i32(15);
    let c16i = b.c_i32(16);
    let c31 = b.c_i32(31);
    let c32 = b.c_i32(32);
    let c63 = b.c_i32(63);
    let c128 = b.c_i32(128);
    let c255 = b.c_i32(255);
    let c256 = b.c_i32(256);

    let tid = b.let_(Op::AndI32(Opnd::Val(tid_full), Opnd::Val(c63)));
    let wave = b.let_(Op::LshrI32(Opnd::Val(tid_full), Opnd::Val(c6)));
    let j = b.let_(Op::AndI32(Opnd::Val(tid), Opnd::Val(c31)));
    let pblk = b.let_(Op::LshrI32(Opnd::Val(tid), Opnd::Val(c5)));
    let g8 = b.shl_i32(pblk, c3);
    let g16 = b.shl_i32(pblk, c4);
    let g_bytes8 = b.shl_i32(pblk, c3);
    let lds_k = b.c_i32(0);
    let dma_l = fmha_t_opt("dma") && !vs_active();
    let lds_v = if dma_l { b.c_i32(16640) } else { b.c_i32(if pp { 256 } else { 128 } * fmha_t_pitch()) };
    let lds_ex = if dma_l { b.c_i32(nbuf * 33280) } else { b.c_i32(if pp { 512 } else { nbuf * 256 } * fmha_t_pitch()) };

    // per-wave exchange slots (own lane, partner lane l ^ 32)
    let wave256 = b.mul_i32(wave, c256);
    let tid4 = b.mul_i32(tid, c4);
    let ex0 = b.add_i32(lds_ex, wave256);
    let ex_own = b.add_i32(ex0, tid4);
    let tid_x = b.xor_i32(tid, c32);
    let tid_x4 = b.mul_i32(tid_x, c4);
    let ex_partner = b.add_i32(ex0, tid_x4);

    let wave32 = b.shl_i32(wave, c5);
    let qt256 = if name.ends_with("_t128") { b.shl_i32(qtile, c7) } else { b.shl_i32(qtile, c8) };
    let row0 = b.add_i32(qt256, wave32);
    let row_raw = b.add_i32(row0, j);
    // rows past the end of a partial query tile reuse the last valid row: they compute and store
    // exactly its (identical) result instead of touching memory out of bounds
    let cm1 = b.c_i32(-1);
    let s_last = b.add_i32(s_len, cm1);
    let row_ok = b.cmp_lt_i32(row_raw, s_len);
    let ablate_pre = std::env::var("FMHA_ABLATE").unwrap_or_default();
    let row = if ablate_pre.contains("noclamp") {
        row_raw
    } else {
        b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(row_ok), a: Opnd::Val(row_raw), b: Opnd::Val(s_last) })
    };
    let q_row_off = b.mul_i32(row, q_seqs);
    let q_b_off = b.mul_i32(bidx, q_bs);
    let q_h_off = b.mul_i32(hidx, q_hs);
    let q_off0 = b.add_i32(q_row_off, q_b_off);
    let q_off1 = b.add_i32(q_off0, q_h_off);
    let q_off = b.add_i32(q_off1, g16);

    // Q fragments (B operand of S^T = K Q^T): same permuted K order as the K fragments
    let mut bq: Vec<ValueId> = Vec::with_capacity(2);
    let mut bq1_words: Vec<ValueId> = Vec::new();
    let mut bq0_words: Vec<ValueId> = Vec::new();
    for c in 0..2u32 {
        let qp = b.ptr_add(ptr_q, q_off);
        let mut w: Vec<ValueId> = Vec::with_capacity(8);
        if fmha_t_opt("qdw") {
            for i in 0..8u32 {
                let off = 64 * c + if i < 4 { 4 * i } else { 32 + 4 * (i - 4) };
                let v = b.load_f32(qp, off);
                w.push(b.bitcast_i32(v));
            }
        } else {
            // two 16-byte loads (words 0-3 and 8-11 of this 64-byte group) instead of eight dword loads
            for half in 0..2u32 {
                let f4 = b.load_b128(qp, 64 * c + 32 * half);
                for k in 0..4u8 {
                    let l = b.frag4_lane(f4, k);
                    w.push(b.bitcast_i32(l));
                }
            }
        }
        if c == 1 {
            bq1_words = w.clone();
        } else {
            bq0_words = w.clone();
        }
        bq.push(b.frag8(w[0], w[1], w[2], w[3], w[4], w[5], w[6], w[7]));
    }
    let c5b = b.c_i32(5);
    let qd_stride = b.let_(Op::LshrI32(Opnd::Val(q_seqs), Opnd::Val(c5b)));
    let kd_stride = b.let_(Op::LshrI32(Opnd::Val(k_seqs), Opnd::Val(c5b)));
    let qd_row = b.mul_i32(row, qd_stride);
    let qd_b = b.mul_i32(bidx, dq_bs);
    let qd_h = b.mul_i32(hidx, dq_hs);
    let qd0 = b.add_i32(qd_row, qd_b);
    let qd1 = b.add_i32(qd0, qd_h);
    let qd_ptr = b.ptr_add(ptr_qd, qd1);
    let qd_raw = b.load_f32(qd_ptr, 0);
    let qd = b.bitcast_i32(qd_raw);
    let sq0 = b.let_(Op::LshrI32(Opnd::Val(qd), Opnd::Val(g8)));
    let sh16 = b.add_i32(g8, c16i);
    let sq1 = b.let_(Op::LshrI32(Opnd::Val(qd), Opnd::Val(sh16)));
    let vd_raw = b.load_f32(ptr_vd, 0);

    // KV head of this query head (GQA ratio is a power of two <= 16)
    let gq2 = b.cmp_lt_i32(c1, gqa);
    let gq4 = b.cmp_lt_i32(c2, gqa);
    let gq8 = b.cmp_lt_i32(c4, gqa);
    let gq16 = b.cmp_lt_i32(c8, gqa);
    let c0k = b.c_i32(0);
    let s1 = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(gq2), a: Opnd::Val(c1), b: Opnd::Val(c0k) });
    let s2 = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(gq4), a: Opnd::Val(c2), b: Opnd::Val(s1) });
    let s3 = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(gq8), a: Opnd::Val(c3), b: Opnd::Val(s2) });
    let gshift = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(gq16), a: Opnd::Val(c4), b: Opnd::Val(s3) });
    let kvh = if ablate_pre.contains("nogqa") { hidx } else { b.let_(Op::LshrI32(Opnd::Val(hidx), Opnd::Val(gshift))) };
    // contract (derivation under the host relations H = HK * gqa, gqa a power of two <= 16, head < H): kv_head = head >> log2(gqa) is in [0, HK - 1]; the interval engine has no rule for a variable shift
    b.assume_trusted(kvh, Ext::c(0), Ext::sym("HK") - Ext::c(1), "kv head = head >> log2(gqa) with head < H = HK * gqa (gqa a power of two <= 16): variable shift, no interval rule");
    let kb0 = b.mul_i32(bidx, k_bs);
    let kb1 = b.mul_i32(kvh, k_hs);
    let kbase_off = b.add_i32(kb0, kb1);
    let vb0 = b.mul_i32(bidx, v_bs);
    let vb1 = b.mul_i32(kvh, v_hs);
    let vbase_off = b.add_i32(vb0, vb1);
    let kd_b = b.mul_i32(bidx, dk_bs);
    let kd_h = b.mul_i32(kvh, dk_hs);
    let kd_base = b.add_i32(kd_b, kd_h);
    // KV split: this block owns the 128-key tiles [split * tps, min(ntiles, (split + 1) * tps)) of the key range; the K/V/K-scale base offsets are shifted
    // by the first key so that every key index inside the kernel is relative to it (kv_len := keys of this split)
    let (kbase_off, vbase_off, kd_base, kv_len) = if let (Some(sp), Some(lg)) = (kvs_split, kvs_lg) {
        let c127k = b.c_i32(127);
        let c7k = b.c_i32(7);
        let cn1 = b.c_i32(-1);
        let nt_r = b.add_i32(kv_len, c127k);
        let ntiles = b.let_(Op::LshrI32(Opnd::Val(nt_r), Opnd::Val(c7k)));
        let one_l = b.shl_i32(c1, lg);
        let spl_m1 = b.add_i32(one_l, cn1);
        let tps_r = b.add_i32(ntiles, spl_m1);
        let tps = b.let_(Op::LshrI32(Opnd::Val(tps_r), Opnd::Val(lg)));
        // host contract of the KV-split launch (the host guard "every split is non-empty": splits <= ceil(SK / 128)): tiles-per-split tps = ceil(ntiles / splits) in [1, ceil(SK/128)],
        // this split's first tile in [0, ceil(SK/128) - 1] (its key row key_lo = 128 * tile_lo <= SK - 1) and the split length kv_eff in [1, SK]; the shifts by a variable log2(splits) have no interval rule
        b.assume_trusted(tps, Ext::c(1), Ext::ka(0x110).ceil_div(128), "tiles per split = ceil(ntiles / splits) in [1, ntiles] (host guard: splits <= ntiles); variable shift by log2(splits)");
        let tile_lo = b.mul_i32(sp, tps);
        b.assume_trusted(tile_lo, Ext::c(0), Ext::ka(0x110).ceil_div(128) - Ext::c(1), "first tile of this split = split * tps <= ntiles - 1 (host guard: every split is non-empty, (splits - 1) * tps < ntiles)");
        let tile_hi_r = b.add_i32(tile_lo, tps);
        let hi_gt = b.cmp_lt_i32(ntiles, tile_hi_r);
        let tile_hi = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(hi_gt), a: Opnd::Val(ntiles), b: Opnd::Val(tile_hi_r) });
        let key_lo = b.shl_i32(tile_lo, c7k);
        // KL names this split's first key row (a free symbol with range [0, +inf)): the analysis cannot correlate key_lo with the split length (kv_eff = key_hi - key_lo, key_hi <= SK), so the
        // correlation is stated through the shared symbol: key_lo = KL and kv_eff <= SK - KL (arithmetic fact of the code below, listed as TRUSTED in the report)
        b.sym_range("KL", 0, i64::MAX);
        b.assume_trusted(key_lo, Ext::sym("KL"), Ext::sym("KL"), "KL is only a NAME for key_lo = tile_lo << 7 (free symbol >= 0) so the next assume can state the correlation with the split length");
        let key_hi_t = b.shl_i32(tile_hi, c7k);
        let hi_lt = b.cmp_lt_i32(key_hi_t, kv_len);
        let key_hi = b.let_(Op::Select { ty: DType::I32, cond: Opnd::Val(hi_lt), a: Opnd::Val(key_hi_t), b: Opnd::Val(kv_len) });
        let key_lo_n = b.mul_i32(key_lo, cn1);
        let kv_eff = b.add_i32(key_hi, key_lo_n);
        b.assume_trusted(kv_eff, Ext::c(1), Ext::ka(0x110) - Ext::sym("KL"), "split length kv_eff = key_hi - key_lo with key_hi = min(tile_hi << 7, SK) <= SK (correlation lost by the interval engine) and >= 1 by the host guard");
        let ko = b.mul_i32(key_lo, k_seqs);
        let vo = b.mul_i32(key_lo, v_seqs);
        let kdo = b.mul_i32(key_lo, kd_stride);
        let kb2 = b.add_i32(kbase_off, ko);
        let vb2 = b.add_i32(vbase_off, vo);
        let kd2 = b.add_i32(kd_base, kdo);
        (kb2, vb2, kd2, kv_eff)
    } else {
        (kbase_off, vbase_off, kd_base, kv_len)
    };

    // wave-group split (which 4 of the 8 waves form role A): FMHA_OPT split0 = waves 0-3 (default), split1 = even waves, split2 = bit-1 of the wave id.
    // The group-local thread id (rt) must stay a permutation of 0..255 inside a group: rt = 64 * (index of the wave in its group) + lane.
    let split_mode = fmha_t_num("split").unwrap_or(0);
    let c3s = b.c_i32(3);
    let wave4_s = match split_mode {
        0 => b.let_(Op::AndI32(Opnd::Val(wave), Opnd::Val(c3s))),
        1 => b.let_(Op::LshrI32(Opnd::Val(wave), Opnd::Val(c1))),
        2 => {
            let lo = b.let_(Op::AndI32(Opnd::Val(wave), Opnd::Val(c1)));
            let c2s = b.c_i32(2);
            let hi0 = b.let_(Op::LshrI32(Opnd::Val(wave), Opnd::Val(c2s)));
            let hi = b.shl_i32(hi0, c1);
            b.add_i32(lo, hi)
        }
        _ => b.let_(Op::AndI32(Opnd::Val(wave), Opnd::Val(c3s))),
    };
    let rt = if split_mode == 0 {
        b.let_(Op::AndI32(Opnd::Val(tid_full), Opnd::Val(c255)))
    } else {
        let c63s = b.c_i32(63);
        let lane_s = b.let_(Op::AndI32(Opnd::Val(tid_full), Opnd::Val(c63s)));
        let c6s = b.c_i32(6);
        let w64 = b.shl_i32(wave4_s, c6s);
        b.add_i32(w64, lane_s)
    };
    let rt_row = b.let_(Op::LshrI32(Opnd::Val(rt), Opnd::Val(c1)));
    let rt_half = b.let_(Op::AndI32(Opnd::Val(rt), Opnd::Val(c1)));
    let rt_half64 = b.shl_i32(rt_half, c6);
    let pitch_c = b.c_i32(fmha_t_pitch());
    let rt_rowp = b.mul_i32(rt_row, pitch_c);
    let rt64 = b.add_i32(rt_rowp, rt_half64);
    let is_a = match split_mode {
        1 => {
            let lo = b.let_(Op::AndI32(Opnd::Val(wave), Opnd::Val(c1)));
            b.cmp_lt_i32(lo, c1)
        }
        2 => {
            let c1b = b.c_i32(1);
            let sh = b.let_(Op::LshrI32(Opnd::Val(wave), Opnd::Val(c1b)));
            let lo = b.let_(Op::AndI32(Opnd::Val(sh), Opnd::Val(c1b)));
            b.cmp_lt_i32(lo, c1b)
        }
        _ => b.cmp_lt_i32(wave, c4),
    };

    // transposing-read lane address for A' = V^T (key of byte b: 16 r + 8 (i/4) + 4 g + i % 4):
    //   key_part = 8 * ((M & 15) >> 3) + 4 g + ((M >> 1) & 3); col_part = 16 * ((M >> 4) & 1) + 8 * (M & 1)
    let m15 = b.let_(Op::AndI32(Opnd::Val(tid), Opnd::Val(c15)));
    let m_h3 = b.let_(Op::LshrI32(Opnd::Val(m15), Opnd::Val(c3)));
    let key_a = b.shl_i32(m_h3, c3);
    let key_b = b.shl_i32(pblk, c2);
    let m_s1 = b.let_(Op::LshrI32(Opnd::Val(tid), Opnd::Val(c1)));
    let key_c = b.let_(Op::AndI32(Opnd::Val(m_s1), Opnd::Val(c3)));
    let key0p = b.add_i32(key_a, key_b);
    let key_part = b.add_i32(key0p, key_c);
    let key_off = if fmha_t_opt("dma") {
        let c1040 = b.c_i32(1040);
        let ku = b.let_(Op::AndI32(Opnd::Val(key_part), Opnd::Val(c7)));
        let kv = b.mul_i32(ku, c1040);
        let kh = b.let_(Op::LshrI32(Opnd::Val(key_part), Opnd::Val(c3)));
        let kh128 = b.mul_i32(kh, c128);
        b.add_i32(kv, kh128)
    } else {
        b.mul_i32(key_part, pitch_c)
    };
    let m_s4 = b.let_(Op::LshrI32(Opnd::Val(tid), Opnd::Val(c4)));
    let m_gl = b.let_(Op::AndI32(Opnd::Val(m_s4), Opnd::Val(c1)));
    let m_h = b.let_(Op::AndI32(Opnd::Val(tid), Opnd::Val(c1)));
    let col_a = b.shl_i32(m_gl, c4);
    let col_b = b.shl_i32(m_h, c3);
    let col_part = b.add_i32(col_a, col_b);
    let tr0 = b.add_i32(key_off, col_part);
    let tr_base = b.add_i32(tr0, lds_v);
    // DMA layout (vendor style): 1040-byte runs of eight rows {u + 8 s}: row R at ((R & 7) + 8 (R >> 6)) 1040 + ((R >> 3) & 7) 128
    let j128 = if fmha_t_opt("dma") {
        let c1040 = b.c_i32(1040);
        let ju = b.let_(Op::AndI32(Opnd::Val(j), Opnd::Val(c7)));
        let jv = b.mul_i32(ju, c1040);
        let jh = b.let_(Op::LshrI32(Opnd::Val(j), Opnd::Val(c3)));
        let jh128 = b.mul_i32(jh, c128);
        b.add_i32(jv, jh128)
    } else {
        b.mul_i32(j, pitch_c)
    };
    let kf0 = b.add_i32(j128, g16);
    let kf_base = b.add_i32(kf0, lds_k);
    let c127p = b.c_i32(127);
    let kv_len_r = b.add_i32(kv_len, c127p);
    let nkv = b.let_(Op::LshrI32(Opnd::Val(kv_len_r), Opnd::Val(c7)));
    // contract: nkv = (kv_len + 127) >> 7 is in [1, ceil(SK / 128)] (SK >= 1; for the KV-split launch kv_len is the split length, >= 1 by the host guard splits <= ceil(SK / 128));
    // the interval engine floors the lower bound of a right shift to 0
    b.assume_trusted(nkv, Ext::c(1), Ext::ka(0x110).ceil_div(128), "nkv = (kv_len + 127) >> 7 with 1 <= kv_len <= SK (KV-split: kv_len is the split length, >= 1 by the host guard splits <= ceil(SK/128)); the engine floors the lower bound of a shift to 0");
    let cm1k = b.c_i32(-1);
    let kv_last = b.add_i32(kv_len, cm1k);
    let g4 = b.shl_i32(pblk, c2);
    let wave4 = wave4_s;
    let mut kfx: Vec<ValueId> = Vec::new();
    let mut trx: Vec<ValueId> = Vec::new();
    let mut swzw: Vec<ValueId> = Vec::new();
    if (fmha_t_opt("swz") && !fmha_t_opt("dma")) || vs_active() {
        // Bank-conflict-free dense layout: rows of 128 bytes, 16-byte chunk c of row r stored at chunk c ^ s(r). s was found by a
        // brute-force search over s(r) = pi(u) ^ (5 (r & 1)), u = (r >> 1) & 7, against two LDS bank models (64 banks / 16 lanes per
        // b128 and 32 lanes per b64; 32 banks / 8 and 16 lanes) for the K fragment reads, the ds_read_b64_tr_b8 V reads and the
        // b128 staging writes (zero conflicts in both): pi swaps bits 0 and 1 of u, i.e. s2 = u2 ^ p, s1 = u0, s0 = u1 ^ p.
        fn swz_s(b: &mut FnBuilder, row: ValueId, _c3: ValueId, _c7: ValueId, _c4: ValueId) -> ValueId {
            let one = b.c_i32(1);
            let two = b.c_i32(2);
            let three = b.c_i32(3);
            let p = b.let_(Op::AndI32(Opnd::Val(row), Opnd::Val(one)));
            let t1 = b.let_(Op::LshrI32(Opnd::Val(row), Opnd::Val(one)));
            let u0 = b.let_(Op::AndI32(Opnd::Val(t1), Opnd::Val(one)));
            let t2 = b.let_(Op::LshrI32(Opnd::Val(row), Opnd::Val(two)));
            let u1 = b.let_(Op::AndI32(Opnd::Val(t2), Opnd::Val(one)));
            let t3 = b.let_(Op::LshrI32(Opnd::Val(row), Opnd::Val(three)));
            let u2 = b.let_(Op::AndI32(Opnd::Val(t3), Opnd::Val(one)));
            let s2 = b.xor_i32(u2, p);
            let s0 = b.xor_i32(u1, p);
            let s2s = b.shl_i32(s2, two);
            let s1s = b.shl_i32(u0, one);
            let a = b.add_i32(s2s, s1s);
            b.add_i32(a, s0)
        }        let s_k = swz_s(&mut b, j, c3, c7, c4);
        let xk0 = b.xor_i32(pblk, s_k);
        let jrow = b.mul_i32(j, c128);
        for k in 0..4i32 {
            let c2k = b.c_i32(2 * k);
            let xk = b.xor_i32(xk0, c2k);
            let xs = b.shl_i32(xk, c4);
            let a0 = b.add_i32(jrow, xs);
            kfx.push(b.add_i32(a0, lds_k));
        }
        let s_v = swz_s(&mut b, key_part, c3, c7, c4);
        let trow = b.mul_i32(key_part, c128);
        let mh8 = b.shl_i32(m_h, c3);
        let trow_c = b.add_i32(trow, mh8);
        let trow_cl = b.add_i32(trow_c, lds_v);
        let z = b.xor_i32(m_gl, s_v);
        for e in 0..4i32 {
            let ce = b.c_i32(2 * e);
            let ch = b.xor_i32(z, ce);
            let chb = b.shl_i32(ch, c4);
            trx.push(b.add_i32(trow_cl, chb));
        }        let s_r = swz_s(&mut b, rt_row, c3, c7, c4);
        let h4 = b.let_(Op::LshrI32(Opnd::Val(rt_half64), Opnd::Val(c4)));
        let rrow = b.mul_i32(rt_row, c128);
        for w in 0..4i32 {
            let cwv = b.c_i32(w);
            let cw = b.add_i32(h4, cwv);
            let cs = b.xor_i32(cw, s_r);
            let off = b.shl_i32(cs, c4);
            swzw.push(b.add_i32(rrow, off));
        }
    }
    if false {
        let j_s1 = b.let_(Op::LshrI32(Opnd::Val(j), Opnd::Val(c1)));
        let f_k0 = b.let_(Op::AndI32(Opnd::Val(j_s1), Opnd::Val(c7)));
        let zero_sw = b.c_i32(0);
        let f_k = if fmha_t_opt("noswz") { zero_sw } else { f_k0 };
        let gbit = pblk;
        let x = b.xor_i32(gbit, f_k);
        let jrow = b.mul_i32(j, c128);
        for k in 0..4i32 {
            let c2k = b.c_i32(2 * k);
            let xk = b.xor_i32(x, c2k);
            let xs = b.shl_i32(xk, c4);
            let a0 = b.add_i32(jrow, xs);
            kfx.push(b.add_i32(a0, lds_k));
        }
        let kp_s1 = b.let_(Op::LshrI32(Opnd::Val(key_part), Opnd::Val(c1)));
        let f_t0 = b.let_(Op::AndI32(Opnd::Val(kp_s1), Opnd::Val(c7)));
        let f_t = if fmha_t_opt("noswz") { zero_sw } else { f_t0 };
        let y = b.xor_i32(m_gl, f_t);
        let trow = b.mul_i32(key_part, c128);
        let mh8 = b.shl_i32(m_h, c3);
        for e in 0..4i32 {
            let c2e = b.c_i32(2 * e);
            let ye = b.xor_i32(y, c2e);
            let ys = b.shl_i32(ye, c4);
            let a0 = b.add_i32(trow, ys);
            let a1 = b.add_i32(a0, mh8);
            trx.push(b.add_i32(a1, lds_v));
        }
    }

    let kvs = if is_kvs {
        let ptr_ohat = b.let_(Op::KernargPtr { offset: 0x270 });
        let ptr_lse = b.let_(Op::KernargPtr { offset: 0x278 });
        let rows_total = b.let_(Op::KernargI32 { offset: 0x284 });
        let heads = b.let_(Op::KernargI32 { offset: 0x140 });
        let part_row0 = b.mul_i32(kvs_split.expect("split"), rows_total);
        let kvl0 = b.let_(Op::KernargI32 { offset: 0x110 });
        let c127t = b.c_i32(127);
        let c7t = b.c_i32(7);
        let kvl_r = b.add_i32(kvl0, c127t);
        let ntiles_total = b.let_(Op::LshrI32(Opnd::Val(kvl_r), Opnd::Val(c7t)));
        let counters = if fmha_t_opt("fused") { Some(b.let_(Op::KernargPtr { offset: 0x288 })) } else { None };
        Some(KvsCtx { ptr_ohat, ptr_lse, part_row0, heads, counters, ntiles_total })
    } else {
        None
    };
    let cx = FmhaTCtx {
        kvs,
        ptr_o,
        ptr_k,
        ptr_v,
        ptr_kd,
        k_seqs,
        v_seqs,
        kd_stride,
        kv_len,
        kv_last,
        g4,
        o_seqs,
        o_hs,
        o_bs,
        bidx,
        hidx,
        row,
        row0,
        s_len,
        g8,
        g_bytes8,
        j,
        kbase_off,
        vbase_off,
        kd_base,
        rt_row,
        rt_half64,
        rt64,
        tr_base,
        kf_base,
        ex_own,
        ex_partner,
        b0: bq[0],
        b1: bq[1],
        sq0,
        sq1,
        vd_raw,
        nkv,
        lds_k,
        lds_v,
        wave4,
        kfx,
        trx,
        swzw,
        bq1_words,
        bq0_words,
    };
    // vsx: short sequences (<= 2 tiles of 128 keys) keep the LUT correction (their error does not average out), long ones skip it (-128 VALU per
    // tile): two complete code copies selected once at kernel start
    if std::env::var("FMHA_ABLATE").unwrap_or_default().split(|c| c == ',').any(|x| x == "quit") {
        return b.finish(); // diagnostic: the kernel exits immediately (launch + dispatch cost only)
    }
    let vsx_split = sv && ((name.ends_with("_vs128") || name.ends_with("_vs5") || name.ends_with("_vs6") || name.ends_with("_vs9")) || is_kvs) && (vs128_vsx() || fmha_t_opt("corrshort"));
    if sv && name.ends_with("_t128") {
        if vs128_vsx() || fmha_t_opt("corrshort") {
            // same two code copies as `_vs128`: sequences with fewer than `cs` (9) tiles of 128 keys keep the LUT correction
            let c9k = b.c_i32(fmha_t_num("cs").unwrap_or(9) as i32);
            let short = b.cmp_lt_i32(cx.nkv, c9k);
            b.begin_if(Opnd::Val(short));
            VS_CORR_FORCE.store(1, std::sync::atomic::Ordering::SeqCst);
            emit_fmha_t128_role(&mut b, &cx, true);
            b.else_();
            VS_CORR_FORCE.store(2, std::sync::atomic::Ordering::SeqCst);
            emit_fmha_t128_role(&mut b, &cx, true);
            b.end_if();
            VS_CORR_FORCE.store(0, std::sync::atomic::Ordering::SeqCst);
        } else {
            emit_fmha_t128_role(&mut b, &cx, true);
        }
        return b.finish();
    }
    if vsx_split && fmha_t_opt("onecopy") {
        // timing diagnostic: only the long-sequence (no LUT) copy is emitted (short sequences lose their correction)
        VS_CORR_FORCE.store(2, std::sync::atomic::Ordering::SeqCst);
        b.begin_if(is_a);
        vs_role_fn(&name)(&mut b, &cx, true);
        b.else_();
        vs_role_fn(&name)(&mut b, &cx, false);
        b.end_if();
        VS_CORR_FORCE.store(0, std::sync::atomic::Ordering::SeqCst);
        return b.finish();
    }
    if vsx_split {
        // short = fewer than `cs` tiles of 128 keys (default 3)
        // the recipe copy is chosen by the TOTAL tile count of the sequence (LUT correction below `cs` = 9 tiles, as in `_vs128`), not by the tiles of one split:
        // identical numerics to `_vs128` per split, and the accuracy of the short-sequence recipe does not depend on how the keys are split
        let c3k = b.c_i32(fmha_t_num("cs").unwrap_or(9) as i32);
        let nk_sel = match cx.kvs { Some(kv) => kv.ntiles_total, None => cx.nkv };
        let short = b.cmp_lt_i32(nk_sel, c3k);
        for pass in 0..2u8 {
            if pass == 0 {
                b.begin_if(Opnd::Val(short));
                VS_CORR_FORCE.store(1, std::sync::atomic::Ordering::SeqCst);
            } else {
                b.else_();
                VS_CORR_FORCE.store(2, std::sync::atomic::Ordering::SeqCst);
            }
            b.begin_if(is_a);
            vs_role_fn(&name)(&mut b, &cx, true);
            b.else_();
            vs_role_fn(&name)(&mut b, &cx, false);
            b.end_if();
        }
        b.end_if();
        VS_CORR_FORCE.store(0, std::sync::atomic::Ordering::SeqCst);
        return b.finish();
    }
    b.begin_if(is_a);
    if pp {
        emit_fmha_pp_role(&mut b, &cx, true);
    } else if sv && name.ends_with("_g3o") {
        emit_fmha_g3o_role(&mut b, &cx, true);
    } else if sv && name.ends_with("_g3") {
        emit_fmha_g3_role(&mut b, &cx, true);
    } else if sv && name.ends_with("_g2") {
        emit_fmha_g2_role(&mut b, &cx, true);
    } else if sv && name.ends_with("_vsm") {
        emit_fmha_vsm_role(&mut b, &cx, true);
    } else if sv && (name.ends_with("_vs128") || name.ends_with("_vs5") || name.ends_with("_vs6") || name.ends_with("_vs9")) {
        vs_role_fn(&name)(&mut b, &cx, true);
    } else if sv && name.ends_with("_vs") {
        emit_fmha_vs_role(&mut b, &cx, true);
    } else if sv {
        emit_fmha_sv_role(&mut b, &cx, true);
    } else {
        emit_fmha_t_role(&mut b, &cx, true);
    }
    b.else_();
    if pp {
        emit_fmha_pp_role(&mut b, &cx, false);
    } else if sv && name.ends_with("_g3o") {
        emit_fmha_g3o_role(&mut b, &cx, false);
    } else if sv && name.ends_with("_g3") {
        emit_fmha_g3_role(&mut b, &cx, false);
    } else if sv && name.ends_with("_g2") {
        emit_fmha_g2_role(&mut b, &cx, false);
    } else if sv && name.ends_with("_vsm") {
        emit_fmha_vsm_role(&mut b, &cx, false);
    } else if sv && (name.ends_with("_vs128") || name.ends_with("_vs5") || name.ends_with("_vs6") || name.ends_with("_vs9")) {
        vs_role_fn(&name)(&mut b, &cx, false);
    } else if sv && name.ends_with("_vs") {
        emit_fmha_vs_role(&mut b, &cx, false);
    } else if sv {
        emit_fmha_sv_role(&mut b, &cx, false);
    } else {
        emit_fmha_t_role(&mut b, &cx, false);
    }
    b.end_if();
    b.finish()
}

// ---------------------------------------------------------------------------------------------
// sched_* microkernels: small loops with a runtime trip count `n` (kernarg offset 8) used to compare
// the scheduler's machine model with hardware and to exercise cross-block / cross-iteration
// scheduling (docs/scheduling.md). Output: per-thread results at o[tid * 64 ..].
// ---------------------------------------------------------------------------------------------

fn sched_begin(name: &str) -> (FnBuilder, ValueId, ValueId, ValueId) {
    // Build-time workgroup-size override for occupancy experiments (SCHED_WG=1024 launches a
    // 16-wave block = 4 waves/SIMD on one CU). The descriptor's `.max_flat_workgroup_size` must
    // cover the launched block size or the dispatch fails, so it has to be set at build time.
    let wg = std::env::var("SCHED_WG").ok().and_then(|v| v.parse::<u32>().ok()).unwrap_or(512);
    let mut b = FnBuilder::new(name, wg);
    b.lds(16384);
    b.arg("o", DType::Ptr, 0, 8);
    b.arg("count", DType::I32, 8, 4);
    let o = b.let_(Op::KernargPtr { offset: 0 });
    let n = b.let_(Op::KernargI32 { offset: 8 });
    let tid = b.let_(Op::WorkitemId);
    (b, o, n, tid)
}

/// Close a counted loop: it += 1; break unless it < n.
fn sched_end_loop(b: &mut FnBuilder, it: VarId, n: ValueId) {
    let c1 = b.c_i32(1);
    let it_next = b.add_i32(it, c1);
    b.set_var(it, it_next);
    let more = b.cmp_lt_i32(it_next, n);
    let stop = b.let_(Op::NotI1(Opnd::Val(more)));
    b.break_if(Opnd::Val(stop));
    b.end_loop();
}

/// 16 independent chains of one VALU op per iteration. kind: 0 = v_mul_f32, 1 = v_max3_f32, 2 = v_exp_f32.
fn sched_valu_kernel(name: &str, kind: u32) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c64 = b.c_i32(64);
    let step = b.c_f32(1.0001);
    let step_i = b.bitcast_i32(step);
    let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0))];
    for k in 0..16 {
        let f = b.c_f32(0.5 + k as f32);
        let fi = b.bitcast_i32(f);
        inits.push((DType::I32, Opnd::Val(fi)));
    }
    let vars = b.begin_loop(&inits);
    let it = vars[0];
    let stepf = b.bitcast_f32(step_i);
    for k in 0..16 {
        let x = b.bitcast_f32(vars[1 + k]);
        let y = match kind {
            0 => b.mul_f32(x, stepf),
            1 => b.max3_f32(x, stepf, stepf),
            _ => b.exp2_f32(x),
        };
        let yi = b.bitcast_i32(y);
        b.set_var(vars[1 + k], yi);
    }
    sched_end_loop(&mut b, it, n);
    let off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, off);
    for k in 0..16 {
        let x = b.bitcast_f32(vars[1 + k]);
        b.store_f32(row, 4 * k as u32, x);
    }
    b.finish()
}

pub fn sched_valu_mul() -> Function {
    sched_valu_kernel("sched_valu_mul", 0)
}
pub fn sched_valu_max3() -> Function {
    sched_valu_kernel("sched_valu_max3", 1)
}
pub fn sched_valu_exp() -> Function {
    sched_valu_kernel("sched_valu_exp", 2)
}

/// In-place scaled MFMA chain, no VALU.
pub fn sched_mfma_chain() -> Function {
    let (mut b, o, n, tid) = sched_begin("sched_mfma_chain");
    let c0 = b.c_i32(0);
    let c64 = b.c_i32(64);
    let ones = b.c_i32(0x38383838_u32 as i32);
    let f4 = b.frag4(ones, ones, ones, ones);
    let a8 = b.cat_frag8(f4, f4);
    let twos = b.c_i32(0x40404040_u32 as i32);
    let f4b = b.frag4(twos, twos, twos, twos);
    let b8 = b.cat_frag8(f4b, f4b);
    let zero = b.frag_zero(DType::Frag16);
    let vars = b.begin_loop(&[(DType::I32, Opnd::Val(c0)), (DType::Frag16, Opnd::Val(zero))]);
    b.var_mfma_scale(vars[1], a8, b8, 127, 127);
    sched_end_loop(&mut b, vars[0], n);
    let off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, off);
    for i in 0..16u8 {
        let l = b.frag16_lane(vars[1], i);
        let x = b.bitcast_f32(l);
        b.store_f32(row, 4 * i as u32, x);
    }
    b.finish()
}

/// Each iteration: S = A x B (zero accumulator), then a VALU post-processing chain over `lanes` of S
/// (sub, exp2, add into a loop-carried sum). Iterations are independent apart from the sum: the
/// MFMA of iteration i+1 can overlap the VALU work of iteration i (software pipelining target).
fn sched_mfma_valu_kernel(name: &str, lanes: u8) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c64 = b.c_i32(64);
    let ones = b.c_i32(0x38383838_u32 as i32);
    let f4 = b.frag4(ones, ones, ones, ones);
    let a8 = b.cat_frag8(f4, f4);
    let twos = b.c_i32(0x40404040_u32 as i32);
    let f4b = b.frag4(twos, twos, twos, twos);
    let b8 = b.cat_frag8(f4b, f4b);
    let zf = b.c_f32(0.0);
    let zi = b.bitcast_i32(zf);
    let m = b.c_f32(1.5);
    let vars = b.begin_loop(&[(DType::I32, Opnd::Val(c0)), (DType::I32, Opnd::Val(zi))]);
    let zero = b.frag_zero(DType::Frag16);
    let s = b.mfma_scale_fp8(a8, b8, zero, 127, 127);
    let mut sum = b.bitcast_f32(vars[1]);
    for r in 0..lanes {
        let l = b.frag16_lane(s, r);
        let v = b.bitcast_f32(l);
        let d = b.sub_f32(v, m);
        let e = b.exp2_f32(d);
        sum = b.add_f32(sum, e);
    }
    let si = b.bitcast_i32(sum);
    b.set_var(vars[1], si);
    sched_end_loop(&mut b, vars[0], n);
    let off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, off);
    let fin = b.bitcast_f32(vars[1]);
    b.store_f32(row, 0, fin);
    b.finish()
}

/// Cross-wave co-issue probe: waves 0-3 run an independent-accumulator scaled-MFMA loop, waves 4-7 a VALU (fma) loop, so each SIMD
/// has one wave of each kind. mode 0 = both, 1 = MFMA waves only, 2 = VALU waves only (the other role skips its loop).
fn sched_coissue_kernel(name: &str, mode: u8, kind: u8) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c64 = b.c_i32(64);
    let c6 = b.c_i32(6);
    let c4 = b.c_i32(4);
    let wave = b.let_(Op::LshrI32(Opnd::Val(tid), Opnd::Val(c6)));
    let is_mfma = b.cmp_lt_i32(wave, c4);
    let off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, off);
    b.begin_if(Opnd::Val(is_mfma));
    if mode != 2 {
        let ones = b.c_i32(0x38383838_u32 as i32);
        let f4 = b.frag4(ones, ones, ones, ones);
        let a8 = b.cat_frag8(f4, f4);
        let twos = b.c_i32(0x40404040_u32 as i32);
        let f4b = b.frag4(twos, twos, twos, twos);
        let b8 = b.cat_frag8(f4b, f4b);
        let zero = b.frag_zero(DType::Frag16);
        let vars = b.begin_loop(&[
            (DType::I32, Opnd::Val(c0)),
            (DType::Frag16, Opnd::Val(zero)),
            (DType::Frag16, Opnd::Val(zero)),
            (DType::Frag16, Opnd::Val(zero)),
            (DType::Frag16, Opnd::Val(zero)),
        ]);
        for k in 1..5 {
            b.var_mfma_scale(vars[k], a8, b8, 127, 127);
        }
        sched_end_loop(&mut b, vars[0], n);
        for k in 1..5usize {
            let l = b.frag16_lane(vars[k], 0);
            let x = b.bitcast_f32(l);
            b.store_f32(row, 4 * k as u32, x);
        }
    }
    b.else_();
    if mode != 1 {
        let one = b.c_f32(1.0001);
        let two = b.c_f32(0.5);
        let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0))];
        for k in 0..16 {
            let f = b.c_f32(1.0 + k as f32);
            let fi = b.bitcast_i32(f);
            inits.push((DType::I32, Opnd::Val(fi)));
        }
        let vars = b.begin_loop(&inits);
        let c4s = b.c_i32(4);
        let cmk = b.c_i32(0x0007_0007);
        let lut_lo = b.c_i32(i32::from_le_bytes([0, 6, 9, 11]));
        let lut_hi = b.c_i32(i32::from_le_bytes([11, 10, 7, 3]));
        let one_f = b.c_f32(1.0);
        for k in 0..16usize {
            let mut x = b.bitcast_f32(vars[1 + k]);
            if kind == 0 {
                for _ in 0..4 {
                    let m = b.mul_f32(x, one);
                    x = b.add_f32(m, two);
                }
            } else {
                // the softmax conversion recipe of the FMHA kernels: pknorm pair, LUT correction (shift/mask/perm/pk_sub), fp8 pack
                let y = b.add_f32(x, two);
                let u = b.cvt_pknorm_pair(x, y);
                let s1 = b.let_(Op::LshrI32(Opnd::Val(u), Opnd::Val(c4s)));
                let s2 = b.let_(Op::AndI32(Opnd::Val(s1), Opnd::Val(cmk)));
                let pm = b.perm_b32(lut_hi, lut_lo, s2);
                let w = b.pk_sub_u16(u, pm);
                let wd = b.cvt_p8x4_from_u16(w, w, one_f);
                x = b.bitcast_f32(wd);
            }
            let xi = b.bitcast_i32(x);
            b.set_var(vars[1 + k], xi);
        }
        sched_end_loop(&mut b, vars[0], n);
        for k in 0..16usize {
            let x = b.bitcast_f32(vars[1 + k]);
            b.store_f32(row, 4 * k as u32, x);
        }
    }
    b.end_if();
    b.finish()
}
pub fn sched_coissue_both() -> Function {
    sched_coissue_kernel("sched_coissue_both", 0, 0)
}
pub fn sched_coissue_mfma() -> Function {
    sched_coissue_kernel("sched_coissue_mfma", 1, 0)
}
pub fn sched_coissue_valu() -> Function {
    sched_coissue_kernel("sched_coissue_valu", 2, 0)
}
pub fn sched_coissue_cboth() -> Function {
    sched_coissue_kernel("sched_coissue_cboth", 0, 1)
}
pub fn sched_coissue_cvalu() -> Function {
    sched_coissue_kernel("sched_coissue_cvalu", 2, 1)
}
/// Intra-wave overlap probe: every wave issues MFMAs (4 independent accumulators x 2 dependent steps) and an independent VALU conversion
/// workload (16 chains of the softmax recipe) per iteration. mode 0 = both (MFMAs first, then the VALU), 1 = MFMA only, 2 = VALU only,
/// 3 = both with the VALU first.
fn sched_ovl_kernel(name: &str, mode: u8) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c64 = b.c_i32(64);
    let off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, off);
    let ones = b.c_i32(0x38383838_u32 as i32);
    let f4 = b.frag4(ones, ones, ones, ones);
    let a8 = b.cat_frag8(f4, f4);
    let twos = b.c_i32(0x40404040_u32 as i32);
    let f4b = b.frag4(twos, twos, twos, twos);
    let b8 = b.cat_frag8(f4b, f4b);
    let zero = b.frag_zero(DType::Frag16);
    let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0))];
    for _ in 0..4 {
        inits.push((DType::Frag16, Opnd::Val(zero)));
    }
    for k in 0..16 {
        let f = b.c_f32(0.1 + 0.01 * k as f32);
        let fi = b.bitcast_i32(f);
        inits.push((DType::I32, Opnd::Val(fi)));
    }
    let vars = b.begin_loop(&inits);
    let c4s = b.c_i32(4);
    let cmk = b.c_i32(0x0007_0007);
    let lut_lo = b.c_i32(i32::from_le_bytes([0, 6, 9, 11]));
    let lut_hi = b.c_i32(i32::from_le_bytes([11, 10, 7, 3]));
    let one_f = b.c_f32(1.0);
    let two_f = b.c_f32(0.5);
    let do_m = |b: &mut FnBuilder| {
        for k in 1..5usize {
            b.var_mfma_scale(vars[k], a8, b8, 127, 127);
            b.var_mfma_scale(vars[k], a8, b8, 127, 127);
        }
    };
    let do_v = |b: &mut FnBuilder| {
        for k in 0..16usize {
            let x = b.bitcast_f32(vars[5 + k]);
            let y = b.add_f32(x, two_f);
            let u = b.cvt_pknorm_pair(x, y);
            let s1 = b.let_(Op::LshrI32(Opnd::Val(u), Opnd::Val(c4s)));
            let s2 = b.let_(Op::AndI32(Opnd::Val(s1), Opnd::Val(cmk)));
            let pm = b.perm_b32(lut_hi, lut_lo, s2);
            let w = b.pk_sub_u16(u, pm);
            let wd = b.cvt_p8x4_from_u16(w, w, one_f);
            let xn = b.bitcast_f32(wd);
            let xi = b.bitcast_i32(xn);
            b.set_var(vars[5 + k], xi);
        }
    };
    match mode {
        0 => {
            do_m(&mut b);
            do_v(&mut b);
        }
        1 => do_m(&mut b),
        2 => do_v(&mut b),
        _ => {
            do_v(&mut b);
            do_m(&mut b);
        }
    }
    sched_end_loop(&mut b, vars[0], n);
    for k in 1..5usize {
        let l = b.frag16_lane(vars[k], 0);
        let x = b.bitcast_f32(l);
        b.store_f32(row, 4 * k as u32, x);
    }
    for k in 0..16usize {
        let x = b.bitcast_f32(vars[5 + k]);
        b.store_f32(row, 4 * (5 + k) as u32, x);
    }
    b.finish()
}
pub fn sched_ovl_both() -> Function {
    sched_ovl_kernel("sched_ovl_both", 0)
}
pub fn sched_ovl_mfma() -> Function {
    sched_ovl_kernel("sched_ovl_mfma", 1)
}
pub fn sched_ovl_valu() -> Function {
    sched_ovl_kernel("sched_ovl_valu", 2)
}
pub fn sched_ovl_vfirst() -> Function {
    sched_ovl_kernel("sched_ovl_vfirst", 3)
}
pub fn sched_mfma_valu16() -> Function {
    sched_mfma_valu_kernel("sched_mfma_valu16", 16)
}
pub fn sched_mfma_valu4() -> Function {
    sched_mfma_valu_kernel("sched_mfma_valu4", 4)
}

/// Loop with an if/else diamond: each arm computes an MFMA and its own consumer chain; the join then does
/// independent VALU work (a second chain on loop-carried state) that can fill the arm's MFMA latency
/// when the join prefix is duplicated into the arms (stage 2).
pub fn sched_diamond() -> Function {
    let (mut b, o, n, tid) = sched_begin("sched_diamond");
    let c0 = b.c_i32(0);
    let c1 = b.c_i32(1);
    let c64 = b.c_i32(64);
    let ones = b.c_i32(0x38383838_u32 as i32);
    let f4 = b.frag4(ones, ones, ones, ones);
    let a8 = b.cat_frag8(f4, f4);
    let twos = b.c_i32(0x40404040_u32 as i32);
    let f4b = b.frag4(twos, twos, twos, twos);
    let b8 = b.cat_frag8(f4b, f4b);
    let zf = b.c_f32(0.0);
    let zi = b.bitcast_i32(zf);
    let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0)), (DType::I32, Opnd::Val(zi))];
    for k in 0..8 {
        let f = b.c_f32(1.0 + k as f32);
        let fi = b.bitcast_i32(f);
        inits.push((DType::I32, Opnd::Val(fi)));
    }
    let vars = b.begin_loop(&inits);
    let it = vars[0];
    let m = b.c_f32(1.5);
    // arm result goes into loop var 1 (sum)
    let odd = b.let_(Op::AndI32(Opnd::Var(it), Opnd::Val(c1)));
    let zero_i = b.c_i32(0);
    let cond = b.cmp_lt_i32(zero_i, odd);
    b.begin_if(Opnd::Val(cond));
    {
        let z = b.frag_zero(DType::Frag16);
        let s = b.mfma_scale_fp8(a8, b8, z, 127, 127);
        let mut sum = b.bitcast_f32(vars[1]);
        for r in 0..4u8 {
            let l = b.frag16_lane(s, r);
            let v = b.bitcast_f32(l);
            let d = b.sub_f32(v, m);
            let e = b.exp2_f32(d);
            sum = b.add_f32(sum, e);
        }
        let si = b.bitcast_i32(sum);
        b.set_var(vars[1], si);
    }
    b.else_();
    {
        let z = b.frag_zero(DType::Frag16);
        let s = b.mfma_scale_fp8(b8, a8, z, 127, 127);
        let mut sum = b.bitcast_f32(vars[1]);
        for r in 0..4u8 {
            let l = b.frag16_lane(s, r);
            let v = b.bitcast_f32(l);
            let d = b.add_f32(v, m);
            let e = b.exp2_f32(d);
            sum = b.add_f32(sum, e);
        }
        let si = b.bitcast_i32(sum);
        b.set_var(vars[1], si);
    }
    b.end_if();
    // join: independent chains on loop-carried state
    for k in 0..8 {
        let x = b.bitcast_f32(vars[2 + k]);
        let y = b.mul_f32(x, m);
        let y2 = b.add_f32(y, m);
        let yi = b.bitcast_i32(y2);
        b.set_var(vars[2 + k], yi);
    }
    sched_end_loop(&mut b, it, n);
    let off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, off);
    let fin = b.bitcast_f32(vars[1]);
    b.store_f32(row, 0, fin);
    for k in 0..8 {
        let x = b.bitcast_f32(vars[2 + k]);
        b.store_f32(row, 4 + 4 * k as u32, x);
    }
    b.finish()
}
/// Occupancy proxy: one loop iteration is shape-wise like one FMHA substep -- a dependent QK
/// MFMA chain, a softmax-like exp/serial-add VALU chain over the score lanes, an fp8
/// quantisation, then a PV MFMA into a loop-carried O accumulator -- followed by one block-wide
/// barrier like the FMHA loop's tile hand-off. The block size (and therefore the number of waves
/// per SIMD on one CU) is a build-time choice (SCHED_WG=256/512/1024 -> 1/2/4 waves/SIMD), so the
/// same instruction stream can be timed at 2 vs 4 waves/SIMD. Used to decide whether a
/// <=128-VGPR split of the FMHA kernel could hide the dependency stalls measured in
/// docs/archive/status.md (round 45 columns); see docs/scheduling.md.
pub fn sched_occ_chain() -> Function {
    let (mut b, o, n, tid) = sched_begin("sched_occ_chain");
    let c0 = b.c_i32(0);
    let c64 = b.c_i32(64);
    let c127 = b.c_i32(127);
    let c123 = b.c_i32(123);
    let ones = b.c_i32(0x38383838_u32 as i32);
    let f4 = b.frag4(ones, ones, ones, ones);
    let a8 = b.cat_frag8(f4, f4);
    let twos = b.c_i32(0x40404040_u32 as i32);
    let f4b = b.frag4(twos, twos, twos, twos);
    let b8 = b.cat_frag8(f4b, f4b);
    let m = b.c_f32(1.5);
    let zf = b.c_f32(0.0);
    let zi = b.bitcast_i32(zf);
    let zero = b.frag_zero(DType::Frag16);
    let vars = b.begin_loop(&[
        (DType::I32, Opnd::Val(c0)),
        (DType::Frag16, Opnd::Val(zero)),
        (DType::I32, Opnd::Val(zi)),
    ]);
    // two 32x32 score tiles, each accumulated over two chained MFMAs (like the QK chain)
    let zero_s = b.frag_zero(DType::Frag16);
    let s0 = b.mfma_scale_fp8(a8, b8, zero_s, c127, c127);
    let s0 = b.mfma_scale_fp8(a8, b8, s0, c127, c127);
    let s1 = b.mfma_scale_fp8(b8, a8, zero_s, c127, c127);
    let s1 = b.mfma_scale_fp8(b8, a8, s1, c127, c127);
    // softmax-like chain: exp2 of every score lane, serial row-sum adds, fp8 quantisation
    let mut sum = b.bitcast_f32(vars[2]);
    let mut words: Vec<ValueId> = Vec::with_capacity(8);
    for s in [s0, s1] {
        let mut exps: Vec<ValueId> = Vec::with_capacity(16);
        for r in 0..16u8 {
            let l = b.frag16_lane(s, r);
            let v = b.bitcast_f32(l);
            let d = b.sub_f32(v, m);
            let e = b.exp2_f32(d);
            sum = b.add_f32(sum, e);
            exps.push(e);
        }
        for q in 0..4usize {
            words.push(b.cvt_pk_fp8x4_f32(exps[4 * q], exps[4 * q + 1], exps[4 * q + 2], exps[4 * q + 3]));
        }
    }
    let p8 = b.frag8(words[0], words[1], words[2], words[3], words[4], words[5], words[6], words[7]);
    // PV-like: the loop-carried O accumulator gets one MFMA on the quantised P
    b.var_mfma_scale(vars[1], a8, p8, c127, c123);
    let si = b.bitcast_i32(sum);
    b.set_var(vars[2], si);
    // tile hand-off between the wave groups of one block
    b.wait_lds(0);
    b.barrier();
    b.wait_lds(0);
    sched_end_loop(&mut b, vars[0], n);
    // One result row per thread with a 128-byte stride: the 16 accumulator lanes plus the scalar sum
    // are 68 bytes, so a 64-byte stride would overlap the next thread's row and the harness hash
    // would depend on which wave wrote last (a race, not a compiler difference).
    let stride = b.c_i32(128);
    let off = b.mul_i32(tid, stride);
    let row = b.ptr_add(o, off);
    let fin = b.bitcast_f32(vars[2]);
    b.store_f32(row, 0, fin);
    for i in 0..16u8 {
        let l = b.frag16_lane(vars[1], i);
        let x = b.bitcast_f32(l);
        b.store_f32(row, 4 + 4 * i as u32, x);
    }
    b.finish()
}

// ---------------------------------------------------------------------------
// Sparse-fp8 MFMA (`v_smfmac_f32_16x16x128_fp8_fp8`) layout probe.
//
// One 64-lane wave. Each experiment keeps its 4-dword D in a distinct register and the dump happens
// after every smfmac has been issued (a fresh V4 per result forces the register allocator to give
// each experiment its own registers, so a WAW race with the previous smfmac's pending writeback
// cannot corrupt a later experiment's zero-initialised accumulator).
//
// Constants are chosen so the anonymous questions have unambiguous answers:
//   * all-ones A and B: D = (number of K positions contracted) -> 64 vs 128 tells us whether one
//     smfmac covers half or all of the 128 keys;
//   * accumulating the two candidate index patterns answers "how many instructions cover all K";
//   * A zeroed on lanes 32..63 answers whether the compressed A data is consumed per lane;
//   * an index selected by a lane mask (tid < 32) answers whether SRC2 is per lane or per wave;
//   * marker dwords in A (1,2,4,8) tell which compressed-A dword feeds which row.
fn probe_smfmac_dump(b: &mut FnBuilder, base: ValueId, slot: usize, d: ValueId) {
    // global_store_dword only carries a 13-bit signed immediate offset, so each 1 KB slot gets its
    // own base pointer (base = o + tid*16).
    let off = b.c_i32((slot * 1024) as i32);
    let row = b.ptr_add(base, off);
    for i in 0..4u8 {
        let bits = b.frag4_lane(d, i);
        let v = b.bitcast_f32(bits);
        b.store_f32(row, 4 * i as u32, v);
    }
}

/// Same for the first four dwords of a sixteen-dword fragment (the msum reference path).
fn probe_smfmac_dump16(b: &mut FnBuilder, base: ValueId, slot: usize, d: ValueId) {
    let off = b.c_i32((slot * 1024) as i32);
    let row = b.ptr_add(base, off);
    for i in 0..4u8 {
        let bits = b.frag16_lane(d, i);
        let v = b.bitcast_f32(bits);
        b.store_f32(row, 4 * i as u32, v);
    }
}

pub fn probe_smfmac_ones() -> Function {
    let mut b = FnBuilder::new("probe_smfmac_ones", 64);
    b.arg("o", DType::Ptr, 0, 8);
    let o = b.let_(Op::KernargPtr { offset: 0 });
    let tid = b.let_(Op::WorkitemId);
    let c16 = b.c_i32(16);
    let lane_off = b.mul_i32(tid, c16);
    let base = b.ptr_add(o, lane_off);

    let ones = b.c_i32(0x38383838u32 as i32); // E4M3 1.0 in all four bytes
    let zero = b.c_i32(0);
    let m1 = b.c_i32(0x38383838u32 as i32); // 1.0
    let m2 = b.c_i32(0x40404040u32 as i32); // 2.0
    let m4 = b.c_i32(0x48484848u32 as i32); // 4.0
    let m8 = b.c_i32(0x50505050u32 as i32); // 8.0

    let a_ones = b.frag4(ones, ones, ones, ones);
    let a_zero = b.frag4(zero, zero, zero, zero);
    let a_mark = b.frag4(m1, m2, m4, m8);
    let b_ones = b.frag8(ones, ones, ones, ones, ones, ones, ones, ones);
    let b_mark = b.frag8(m1, m2, m4, m8, m1, m2, m4, m8);
    let c0 = b.frag_zero(DType::Frag4);

    // 2-bit-pair fields, LSB first: 0x44.. -> pairs (0,1), 0xee.. -> pairs (2,3), 0x55.. -> (1,1).
    let i01 = b.c_i32(0x44444444u32 as i32);
    let i23 = b.c_i32(0xeeeeeeeeu32 as i32);
    let i11 = b.c_i32(0x55555555u32 as i32);
    let c32 = b.c_i32(32);
    let lt32 = b.cmp_lt_i32(tid, c32);
    let sel_idx = b.let_(Op::Select { ty: DType::I32, cond: lt32.into(), a: i01.into(), b: i23.into() });
    let sel_a = b.let_(Op::Select { ty: DType::I32, cond: lt32.into(), a: ones.into(), b: zero.into() });
    let a_lane = b.frag4(sel_a, sel_a, sel_a, sel_a);

    let mut results: Vec<ValueId> = Vec::new();
    // 0/1: one smfmac with each index pattern, all-ones A and B -> contracted K positions.
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, c0));
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i23, c0));
    // 2: both patterns accumulated -> full 128-key row sum if complementary.
    let d = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, c0);
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i23, d));
    // 3: reversed order.
    let d = b.smfmac_fp8_16x16x128(a_ones, b_ones, i23, c0);
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, d));
    // 4: three instructions (01, 23, 01) -> 192 if additive.
    let d = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, c0);
    let d = b.smfmac_fp8_16x16x128(a_ones, b_ones, i23, d);
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, d));
    // 5: duplicate of slot 0 (detects any remaining cross-experiment register reuse).
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, c0));
    // 6: degenerate pattern (1,1).
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, i11, c0));
    // 7: zero A -> D must be zero.
    results.push(b.smfmac_fp8_16x16x128(a_zero, b_ones, i01, c0));
    // 8: per-lane SRC2 (lanes 0..31 use 0x44, lanes 32..63 use 0xee).
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_ones, sel_idx, c0));
    // 9: A zeroed on lanes 32..63 -> which D elements depend on those lanes' A data.
    results.push(b.smfmac_fp8_16x16x128(a_lane, b_ones, i01, c0));
    // 10/11: marker A dwords (1,2,4,8) with all-ones B: D = sum of selected A dword values, so the
    //        per-D-dword totals reveal which compressed-A dword feeds which rows.
    results.push(b.smfmac_fp8_16x16x128(a_mark, b_ones, i01, c0));
    results.push(b.smfmac_fp8_16x16x128(a_mark, b_ones, i23, c0));
    // 12/13: marker B dwords with all-ones A: which dense-B dword is selected by each index pattern.
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_mark, i01, c0));
    results.push(b.smfmac_fp8_16x16x128(a_ones, b_mark, i23, c0));

    // 14: current row-sum reference: two accumulated scaled MFMAs (msum), A = all-ones 8-dword
    //     fragment, B = the two P halves; the first four D dwords are dumped.
    let ones8 = b.frag8(ones, ones, ones, ones, ones, ones, ones, ones);
    let z16 = b.frag_zero(DType::Frag16);
    let c127 = b.c_i32(127);
    let p1 = b.frag8(m1, m2, m4, m8, m1, m2, m4, m8);
    let p2 = b.frag8(m8, m4, m2, m1, m8, m4, m2, m1);
    let m0 = b.mfma_scale_fp8(ones8, p1, z16, c127, c127);
    let msum = b.mfma_scale_fp8(ones8, p2, m0, c127, c127);
    // 15-18: smfmac variants on the same P halves (accumulating chains; see the dword-3 hazard note).
    let s15a = b.smfmac_fp8_16x16x128(a_ones, p1, i01, c0);
    let s15 = b.smfmac_fp8_16x16x128(a_ones, p2, i23, s15a);
    let s16a = b.smfmac_fp8_16x16x128(a_ones, p1, i01, c0);
    let s16 = b.smfmac_fp8_16x16x128(a_ones, p2, i01, s16a);
    let s17a = b.smfmac_fp8_16x16x128(a_ones, p1, i01, c0);
    let s17 = b.smfmac_fp8_16x16x128(a_ones, p1, i23, s17a);
    let s18a = b.smfmac_fp8_16x16x128(a_ones, p1, i01, c0);
    let s18b = b.smfmac_fp8_16x16x128(a_ones, p1, i23, s18a);
    let s18c = b.smfmac_fp8_16x16x128(a_ones, p2, i01, s18b);
    let s18 = b.smfmac_fp8_16x16x128(a_ones, p2, i23, s18c);

    // 19/20: is the 4th D dword written at all? Pre-initialise the accumulator to a known value
    //        (1000.0f) and check that a single smfmac adds exactly 64 (ones A/B) to every dword.
    let k1000 = b.c_i32(0x447A0000u32 as i32);
    let acc19 = b.frag4(k1000, k1000, k1000, k1000);
    let s19 = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, acc19);
    let acc20 = b.frag4(k1000, k1000, k1000, k1000);
    let s20a = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, acc20);
    let s20 = b.smfmac_fp8_16x16x128(a_ones, b_ones, i23, s20a);
    // 23-26: row-sum mapping with a *lane-dependent* P (even lanes 1.0, odd lanes 2.0), so the row
    //        sums differ and a wrong P-half/index pairing shows up. 23 = msum reference.
    let c1i = b.c_i32(1);
    let oddbit = b.let_(Op::AndI32(Opnd::Val(tid), Opnd::Val(c1i)));
    let lane_is_even = b.cmp_lt_i32(oddbit, c1i);
    let lane_val = b.let_(Op::Select { ty: DType::I32, cond: lane_is_even.into(), a: m1.into(), b: m2.into() });
    let pv = b.frag8(lane_val, lane_val, lane_val, lane_val, lane_val, lane_val, lane_val, lane_val);
    let m23 = b.mfma_scale_fp8(ones8, pv, z16, c127, c127);
    let m23b = b.mfma_scale_fp8(ones8, pv, m23, c127, c127);
    let s24a = b.smfmac_fp8_16x16x128(a_ones, pv, i01, c0);
    let s24 = b.smfmac_fp8_16x16x128(a_ones, pv, i23, s24a);
    let s25a = b.smfmac_fp8_16x16x128(a_ones, pv, i01, c0);
    let s25 = b.smfmac_fp8_16x16x128(a_ones, pv, i01, s25a);
    let s26a = b.smfmac_fp8_16x16x128(a_ones, pv, i01, c0);
    let s26 = b.smfmac_fp8_16x16x128(a_ones, pv, i01, s26a);

    // 27: preset accumulator dumped WITHOUT any smfmac - control for the dump/read path itself.
    let acc27 = b.frag4(k1000, k1000, k1000, k1000);
    // 28/29: preset + single smfmac, read back through VALU (forcing a VALU consumer) and dumped as a
    //        sum (28) and as a rebuilt fragment (29).
    let acc28 = b.frag4(k1000, k1000, k1000, k1000);
    let s28 = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, acc28);
    let b28_0 = b.frag4_lane(s28, 0);
    let b28_1 = b.frag4_lane(s28, 1);
    let b28_2 = b.frag4_lane(s28, 2);
    let b28_3 = b.frag4_lane(s28, 3);
    let v28_0 = b.bitcast_f32(b28_0);
    let v28_1 = b.bitcast_f32(b28_1);
    let v28_2 = b.bitcast_f32(b28_2);
    let v28_3 = b.bitcast_f32(b28_3);
    let sum28a = b.add_f32(v28_0, v28_1);
    let sum28b = b.add_f32(v28_2, v28_3);
    let sum28 = b.add_f32(sum28a, sum28b);
    let acc29 = b.frag4(k1000, k1000, k1000, k1000);
    let s29 = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, acc29);
    let l29_0 = b.frag4_lane(s29, 0);
    let l29_1 = b.frag4_lane(s29, 1);
    let l29_2 = b.frag4_lane(s29, 2);
    let l29_3 = b.frag4_lane(s29, 3);
    let i29_0 = b.bitcast_i32(l29_0);
    let i29_1 = b.bitcast_i32(l29_1);
    let i29_2 = b.bitcast_i32(l29_2);
    let i29_3 = b.bitcast_i32(l29_3);
    let r29 = b.frag4(i29_0, i29_1, i29_2, i29_3);

    // 30-33: how much VALU work between the accumulator pre-set and the smfmac makes the C read
    //        visible? The filler chain is *stored* (slots 60+) so it cannot be dead-code-eliminated.
    let c1f = b.c_f32(1.0);
    let mut prev = b.c_f32(0.0);
    let mut s35: Vec<ValueId> = Vec::new();
    for &(slot, extra) in &[(30usize, 0usize), (31, 1), (32, 2), (33, 4)] {
        let acc = b.frag4(k1000, k1000, k1000, k1000);
        let mut filler = prev;
        for _ in 0..extra {
            filler = b.add_f32(filler, c1f);
        }
        prev = filler;
        let s = b.smfmac_fp8_16x16x128(a_ones, b_ones, i01, acc);
        let l0 = b.frag4_lane(s, 0);
        let l1 = b.frag4_lane(s, 1);
        let l2 = b.frag4_lane(s, 2);
        let l3 = b.frag4_lane(s, 3);
        let i0 = b.bitcast_i32(l0);
        let i1 = b.bitcast_i32(l1);
        let i2 = b.bitcast_i32(l2);
        let i3 = b.bitcast_i32(l3);
        s35.push(b.frag4(i0, i1, i2, i3));
        // keep the filler chain alive: one store per filler variant into its own slot
        let off_f = b.c_i32(((60 + extra) * 1024) as i32);
        let row_f = b.ptr_add(base, off_f);
        b.store_f32(row_f, 0, filler);
    }
    // 40-44: which P Frag8 goes into which smfmac / index pattern? P_a depends on the lane, P_b is a
    //        constant 4.0, so the three pairings give different results. 44 = msum reference.
    let p_a = b.frag8(lane_val, lane_val, lane_val, lane_val, lane_val, lane_val, lane_val, lane_val);
    let p_b = b.frag8(m4, m4, m4, m4, m4, m4, m4, m4);
    let m44 = b.mfma_scale_fp8(ones8, p_a, z16, c127, c127);
    let m44b = b.mfma_scale_fp8(ones8, p_b, m44, c127, c127);
    let s40a = b.smfmac_fp8_16x16x128(a_ones, p_a, i01, c0);
    let s40 = b.smfmac_fp8_16x16x128(a_ones, p_b, i23, s40a);
    let s41a = b.smfmac_fp8_16x16x128(a_ones, p_a, i01, c0);
    let s41 = b.smfmac_fp8_16x16x128(a_ones, p_b, i01, s41a);
    let s42a = b.smfmac_fp8_16x16x128(a_ones, p_a, i01, c0);
    let s42 = b.smfmac_fp8_16x16x128(a_ones, p_a, i23, s42a);
    let s43a = b.smfmac_fp8_16x16x128(a_ones, p_b, i01, c0);
    let s43 = b.smfmac_fp8_16x16x128(a_ones, p_a, i23, s43a);

    for (e, d) in results.iter().enumerate() {
        probe_smfmac_dump(&mut b, base, e, *d);
    }
    for (k, d) in s35.iter().enumerate() {
        probe_smfmac_dump(&mut b, base, 30 + k, *d);
    }
    probe_smfmac_dump16(&mut b, base, 44, m44b);
    probe_smfmac_dump(&mut b, base, 40, s40);
    probe_smfmac_dump(&mut b, base, 41, s41);
    probe_smfmac_dump(&mut b, base, 42, s42);
    probe_smfmac_dump(&mut b, base, 43, s43);
    probe_smfmac_dump(&mut b, base, 27, acc27);
    let off28 = b.c_i32(28 * 1024);
    let row28 = b.ptr_add(base, off28);
    b.store_f32(row28, 0, sum28);
    probe_smfmac_dump(&mut b, base, 29, r29);
    probe_smfmac_dump(&mut b, base, 19, s19);
    probe_smfmac_dump(&mut b, base, 20, s20);
    probe_smfmac_dump16(&mut b, base, 23, m23b);
    probe_smfmac_dump(&mut b, base, 24, s24);
    probe_smfmac_dump(&mut b, base, 25, s25);
    probe_smfmac_dump(&mut b, base, 26, s26);
    probe_smfmac_dump16(&mut b, base, 14, msum);
    probe_smfmac_dump(&mut b, base, 15, s15);
    probe_smfmac_dump(&mut b, base, 16, s16);
    probe_smfmac_dump(&mut b, base, 17, s17);
    probe_smfmac_dump(&mut b, base, 18, s18);
    b.finish()
}


// ---------------------------------------------------------------------------
// gpu-semantics audit attack kernels (not shipped; used by gpu-semantics-occ)
// ---------------------------------------------------------------------------

/// ATTACK: false contract. The kernel claims a 1 MiB extent for a pointer the host may allocate much
/// smaller; the verifier should not treat the declaration as host truth beyond checking it.
pub fn gv_attack_false_contract() -> Function {
    let mut b = FnBuilder::new("gv_attack_false_contract", 64);
    b.arg_tensor("q", Ext::c(1 << 20));
    b.arg("q", DType::Ptr, 0, 8);
    b.arg("o", DType::Ptr, 8, 8);
    b.arg_tensor("o", Ext::c(64));
    let q = b.let_(Op::KernargPtr { offset: 0 });
    let o = b.let_(Op::KernargPtr { offset: 8 });
    let c4096 = b.c_i32(4096);
    let p = b.ptr_add(q, c4096);
    let v = b.load_f32(p, 0);
    b.store_f32(o, 0, v);
    b.finish()
}

/// ATTACK: `assume` on a loop variable that is violated by `set_var` (only Info in v1), then an OOB
/// global access justified by the assumed range.
pub fn gv_attack_assume_loop() -> Function {
    let mut b = FnBuilder::new("gv_attack_assume_loop", 64);
    b.arg_tensor("q", Ext::c(64));
    b.arg("q", DType::Ptr, 0, 8);
    b.arg("o", DType::Ptr, 8, 8);
    b.arg_tensor("o", Ext::c(64));
    let q = b.let_(Op::KernargPtr { offset: 0 });
    let o = b.let_(Op::KernargPtr { offset: 8 });
    b.allow_var_rereads();
    let c0 = b.c_i32(0);
    let c1 = b.c_i32(1);
    let c4 = b.c_i32(4);
    let vars = b.begin_loop(&[(DType::I32, Opnd::Val(c0))]);
    let i = vars[0];
    b.assume(Opnd::Var(i), Ext::c(0), Ext::c(0));
    let ni = b.add_i32(Opnd::Var(i), c1);
    b.set_var(i, ni);
    let off = b.mul_i32(Opnd::Var(i), c4);
    let p = b.ptr_add(q, off);
    let v = b.load_f32(p, 0);
    b.store_f32(o, 0, v);
    b.end_loop();
    b.finish()
}

/// ATTACK: constant LDS access past the declared 256-byte segment.
pub fn gv_attack_lds_const() -> Function {
    let mut b = FnBuilder::new("gv_attack_lds_const", 64);
    b.lds(256);
    b.arg("o", DType::Ptr, 0, 8);
    b.arg_tensor("o", Ext::c(64));
    let o = b.let_(Op::KernargPtr { offset: 0 });
    let c512 = b.c_i32(512);
    let raw = b.load_lds_b32(Opnd::Val(c512));
    let v = b.bitcast_f32(Opnd::Val(raw));
    b.store_f32(o, 0, v);
    b.finish()
}

/// ATTACK: descriptor num_records (4096) overstates a 64-byte declared extent.
pub fn gv_attack_desc_over() -> Function {
    let mut b = FnBuilder::new("gv_attack_desc_over", 64);
    b.arg_tensor("q", Ext::c(64));
    b.arg("q", DType::Ptr, 0, 8);
    b.arg("o", DType::Ptr, 8, 8);
    b.arg_tensor("o", Ext::c(64));
    let q = b.let_(Op::KernargPtr { offset: 0 });
    let o = b.let_(Op::KernargPtr { offset: 8 });
    let c0 = b.c_i32(0);
    let r = b.buffer_desc(q, 4096);
    let v = b.buffer_load_f32(r, c0, c0, 0);
    b.store_f32(o, 0, v);
    b.finish()
}

/// ATTACK: min-clamp is applied only on one branch; the merged pointer bound must not become trusted
/// if the other branch is unclamped.
pub fn gv_attack_clamp_path() -> Function {
    let mut b = FnBuilder::new("gv_attack_clamp_path", 64);
    b.arg_tensor("q", Ext::c(512));
    b.arg("q", DType::Ptr, 0, 8);
    b.arg("o", DType::Ptr, 8, 8);
    b.arg_tensor("o", Ext::c(64));
    let q = b.let_(Op::KernargPtr { offset: 0 });
    let o = b.let_(Op::KernargPtr { offset: 8 });
    let tid = b.let_(Op::WorkitemId);
    let c0 = b.c_i32(0);
    let c127 = b.c_i32(127);
    let c4 = b.c_i32(4);
    let c16 = b.c_i32(16);
    let off = b.mul_i32(tid, c16);
    let clamped = b.min_i32(off, c127);
    let c32 = b.c_i32(32);
    let pick = b.cmp_lt_i32(tid, c32);
    b.begin_if(Opnd::Val(pick));
    let p1 = b.ptr_add(q, clamped);
    let v1 = b.load_f32(p1, 0);
    b.store_f32(o, 0, v1);
    b.else_();
    let p2 = b.ptr_add(q, off);
    let v2 = b.load_f32(p2, 0);
    b.store_f32(o, 0, v2);
    b.end_if();
    b.finish()
}

/// ATTACK (trust boundary): `assume_trusted` can certify an access the loop actually violates.
pub fn gv_attack_assume_trusted() -> Function {
    let mut b = FnBuilder::new("gv_attack_assume_trusted", 64);
    b.arg_tensor("q", Ext::c(64));
    b.arg("q", DType::Ptr, 0, 8);
    b.arg("o", DType::Ptr, 8, 8);
    b.arg_tensor("o", Ext::c(64));
    let q = b.let_(Op::KernargPtr { offset: 0 });
    let o = b.let_(Op::KernargPtr { offset: 8 });
    let c0 = b.c_i32(0);
    let c1 = b.c_i32(1);
    let c4 = b.c_i32(4);
    let vars = b.begin_loop(&[(DType::I32, Opnd::Val(c0))]);
    let i = vars[0];
    b.assume_trusted(Opnd::Var(i), Ext::c(0), Ext::c(0), "loop exits before i reaches 1");
    let ni = b.add_i32(Opnd::Var(i), c1);
    b.set_var(i, ni);
    let off = b.mul_i32(Opnd::Var(i), c4);
    let p = b.ptr_add(q, off);
    let v = b.load_f32(p, 0);
    b.store_f32(o, 0, v);
    b.end_loop();
    b.finish()
}

/// AUDIT: unsafe global-region protocol made "certified" by the counted `buf_trust` escape. There is
/// no completion/release/acquire; the region check is skipped and the ledger must expose the trust.
pub fn gv_audit_region_trust() -> Function {
    let mut b = FnBuilder::new("gv_audit_region_trust", 128);
    b.arg("buf", DType::Ptr, 0, 8);
    b.arg_tensor("buf", Ext::c(8192));
    b.buf_region("r", "buf", Ext::c(0), Ext::c(8192));
    b.buf_trust("r", "host launch order / cross-kernel visibility argued outside the verifier");
    let p = b.let_(Op::KernargPtr { offset: 0 });
    let t = b.let_(Op::WorkitemId);
    let c64 = b.c_i32(64);
    let is_p = b.cmp_lt_i32(t, c64);
    b.begin_if(Opnd::Val(is_p));
    b.buf_produce("r", Opnd::I32(0));
    b.store_f32(p, 0, Opnd::F32(1.0));
    b.tile_end();
    b.buf_consume("r", Opnd::I32(0));
    let _ = b.load_f32(p, 0);
    b.tile_end();
    b.end_if();
    b.finish()
}

// ---------------------------------------------------------------------------------------------
// probe_agpr_*: AGPR support probes (docs/agpr.md). The three variants compute the same thing: a scaled-MFMA accumulation loop whose A/B
// fragments come from LDS. `ref` keeps everything in arch VGPRs; `acc` pins the accumulator in AGPRs (acc_cd form MFMA); `full` also reads the
// fragments with ds_read_b128 straight into AGPRs. Output (identical for all three): per-thread 16 accumulator lanes at o[tid * 64 ..].
// ---------------------------------------------------------------------------------------------
fn probe_agpr_kernel(name: &str, pin_acc: bool, pin_frags: bool, acc_base: Option<u32>) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c16 = b.c_i32(16);
    let c64 = b.c_i32(64);
    let c8192 = b.c_i32(8192);
    let mul = b.c_i32(0x01010101);
    let add = b.c_i32(0x04030201);
    let mask = b.c_i32(0x3f3f3f3f);
    let t1 = b.mul_i32(tid, mul);
    let t2 = b.add_i32(t1, add);
    let w = b.let_(Op::AndI32(Opnd::Val(t2), Opnd::Val(mask)));
    let data = b.frag4(w, w, w, w);
    let off = b.mul_i32(tid, c16);
    let off2 = b.add_i32(off, c8192);
    b.store_lds_b128(Opnd::Val(off), Opnd::Val(data));
    b.store_lds_b128(Opnd::Val(off2), Opnd::Val(data));
    b.wait_lds(0);
    b.barrier();
    b.wait_lds(0);
    let mut a8 = b.load_lds_b128x2(Opnd::Val(off), Opnd::Val(off2));
    let mut b8 = b.load_lds_b128x2(Opnd::Val(off2), Opnd::Val(off));
    if pin_frags {
        a8 = b.agpr(a8);
        b8 = b.agpr(b8);
    }
    let zero = b.frag_zero(DType::Frag16);
    let vars = b.begin_loop(&[(DType::I32, Opnd::Val(c0)), (DType::Frag16, Opnd::Val(zero))]);
    if pin_acc {
        match acc_base {
            Some(base) => b.pin_agpr_at(vars[1], base),
            None => b.pin_agpr(vars[1]),
        }
    }
    b.var_mfma_scale(vars[1], a8, b8, 127, 127);
    sched_end_loop(&mut b, vars[0], n);
    let row_off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, row_off);
    for i in 0..16u8 {
        let l = b.frag16_lane(vars[1], i);
        let x = b.bitcast_f32(l);
        b.store_f32(row, 4 * i as u32, x);
    }
    b.finish()
}

pub fn probe_agpr_ref() -> Function {
    probe_agpr_kernel("probe_agpr_ref", false, false, None)
}
pub fn probe_agpr_acc() -> Function {
    probe_agpr_kernel("probe_agpr_acc", true, false, None)
}
pub fn probe_agpr_full() -> Function {
    probe_agpr_kernel("probe_agpr_full", true, true, None)
}
/// Accumulator pinned at a[64:79] (exact placement), fragments in AGPRs.
pub fn probe_agpr_pinned() -> Function {
    probe_agpr_kernel("probe_agpr_pinned", true, true, Some(64))
}

/// The 4-wave GEMM mix in miniature (docs/agpr.md): four 16x16x128 scaled-MFMA accumulators (Frag4), A/B fragments read from LDS. `mix`: accumulators 0 and 1 live
/// in AGPRs (acc_cd form, pinned at a[96:99] / a[100:103]) next to two VGPR accumulators (vgpr form), and the fragments are read straight into AGPRs.
fn probe_agpr_m16_kernel(name: &str, mix: bool) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c16 = b.c_i32(16);
    let c64 = b.c_i32(64);
    let c8192 = b.c_i32(8192);
    let c127 = b.c_i32(127);
    let mul = b.c_i32(0x01010101);
    let add = b.c_i32(0x04030201);
    let mask = b.c_i32(0x3f3f3f3f);
    let t1 = b.mul_i32(tid, mul);
    let t2 = b.add_i32(t1, add);
    let w = b.let_(Op::AndI32(Opnd::Val(t2), Opnd::Val(mask)));
    let data = b.frag4(w, w, w, w);
    let off = b.mul_i32(tid, c16);
    let off2 = b.add_i32(off, c8192);
    b.store_lds_b128(Opnd::Val(off), Opnd::Val(data));
    b.store_lds_b128(Opnd::Val(off2), Opnd::Val(data));
    b.wait_lds(0);
    b.barrier();
    b.wait_lds(0);
    let mut a8 = b.load_lds_b128x2(Opnd::Val(off), Opnd::Val(off2));
    let mut b8 = b.load_lds_b128x2(Opnd::Val(off2), Opnd::Val(off));
    if mix {
        a8 = b.agpr(a8);
        b8 = b.agpr(b8);
    }
    let zero = b.frag_zero(DType::Frag4);
    let vars = b.begin_loop(&[
        (DType::I32, Opnd::Val(c0)),
        (DType::Frag4, Opnd::Val(zero)),
        (DType::Frag4, Opnd::Val(zero)),
        (DType::Frag4, Opnd::Val(zero)),
        (DType::Frag4, Opnd::Val(zero)),
    ]);
    if mix {
        b.pin_agpr_at(vars[1], 96);
        b.pin_agpr_at(vars[2], 100);
    }
    b.var_mfma_scale16(vars[1], a8, b8, c127, c127, 0, 0);
    b.var_mfma_scale16(vars[2], b8, a8, c127, c127, 0, 0);
    b.var_mfma_scale16(vars[3], a8, b8, c127, c127, 1, 0);
    b.var_mfma_scale16(vars[4], b8, a8, c127, c127, 0, 1);
    sched_end_loop(&mut b, vars[0], n);
    let row_off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, row_off);
    for (q, v) in vars[1..].iter().enumerate() {
        for i in 0..4u8 {
            let l = b.frag4_lane(*v, i);
            let x = b.bitcast_f32(l);
            b.store_f32(row, 4 * (4 * q as u32 + i as u32), x);
        }
    }
    b.finish()
}

pub fn probe_agpr_m16_ref() -> Function {
    probe_agpr_m16_kernel("probe_agpr_m16_ref", false)
}
pub fn probe_agpr_m16_mix() -> Function {
    probe_agpr_m16_kernel("probe_agpr_m16_mix", true)
}

/// In-place reload of loop-carried AGPR fragments (the 4-wave GEMM pattern): tile t's A/B fragments are loop variables read by the MFMAs; right after
/// their last use the fragments of tile t+1 are read from LDS straight into the same registers (`set_var(var, load_lds_b128x2(..))` is coalesced into
/// the variable). `inplace`: the variables and the accumulator live in AGPRs and the reload is the coalesced form; the reference reloads through
/// `cat_frag8` copies in plain VGPRs. Both print the same 4 accumulator lanes per thread.
fn probe_agpr_reload_kernel(name: &str, inplace: bool) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c1 = b.c_i32(1);
    let c16 = b.c_i32(16);
    let c64 = b.c_i32(64);
    let c8192 = b.c_i32(8192);
    let c127 = b.c_i32(127);
    let mul = b.c_i32(0x01010101);
    let add = b.c_i32(0x04030201);
    let mask = b.c_i32(0x3f3f3f3f);
    let t1 = b.mul_i32(tid, mul);
    let t2 = b.add_i32(t1, add);
    let w = b.let_(Op::AndI32(Opnd::Val(t2), Opnd::Val(mask)));
    let w1 = b.add_i32(w, mul);
    let data0 = b.frag4(w, w, w, w);
    let data1 = b.frag4(w1, w1, w1, w1);
    let off = b.mul_i32(tid, c16);
    let off2 = b.add_i32(off, c8192);
    b.store_lds_b128(Opnd::Val(off), Opnd::Val(data0));
    b.store_lds_b128(Opnd::Val(off2), Opnd::Val(data1));
    b.wait_lds(0);
    b.barrier();
    b.wait_lds(0);
    let a_init = b.load_lds_b128x2(Opnd::Val(off), Opnd::Val(off2));
    let b_init = b.load_lds_b128x2(Opnd::Val(off2), Opnd::Val(off));
    let zero = b.frag_zero(DType::Frag4);
    let vars = b.begin_loop(&[
        (DType::I32, Opnd::Val(c0)),
        (DType::Frag4, Opnd::Val(zero)),
        (DType::Frag8, Opnd::Val(a_init)),
        (DType::Frag8, Opnd::Val(b_init)),
    ]);
    let (it, acc, av, bv) = (vars[0], vars[1], vars[2], vars[3]);
    if inplace {
        b.pin_agpr(acc);
        b.pin_agpr(av);
        b.pin_agpr(bv);
    }
    b.var_mfma_scale16(acc, Opnd::Var(av), Opnd::Var(bv), c127, c127, 0, 0);
    // next tile: alternate the LDS region so every iteration's fragments differ
    let nxt = b.add_i32(it, c1);
    let par = b.let_(Op::AndI32(Opnd::Val(nxt), Opnd::Val(c1)));
    let r0 = b.mul_i32(par, c8192);
    let r1 = b.xor_i32(r0, c8192);
    let la = b.add_i32(off, r0);
    let lb = b.add_i32(off, r1);
    if inplace {
        let na = b.load_lds_b128x2(Opnd::Val(la), Opnd::Val(lb));
        b.set_var(av, na);
        let nb = b.load_lds_b128x2(Opnd::Val(lb), Opnd::Val(la));
        b.set_var(bv, nb);
    } else {
        let a_lo = b.load_lds_b128(Opnd::Val(la));
        let a_hi = b.load_lds_b128(Opnd::Val(lb));
        let na = b.cat_frag8(a_lo, a_hi);
        b.set_var(av, na);
        let b_lo = b.load_lds_b128(Opnd::Val(lb));
        let b_hi = b.load_lds_b128(Opnd::Val(la));
        let nb = b.cat_frag8(b_lo, b_hi);
        b.set_var(bv, nb);
    }
    sched_end_loop(&mut b, it, n);
    let row_off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, row_off);
    for i in 0..4u8 {
        let l = b.frag4_lane(acc, i);
        let x = b.bitcast_f32(l);
        b.store_f32(row, 4 * i as u32, x);
    }
    b.finish()
}

pub fn probe_agpr_reload_ref() -> Function {
    probe_agpr_reload_kernel("probe_agpr_reload_ref", false)
}
pub fn probe_agpr_reload() -> Function {
    probe_agpr_reload_kernel("probe_agpr_reload", true)
}

/// The GEMM reload pattern with several fragment pairs: MFMA j reads (av[j], bv[j]); right after it both are reloaded in place for the next tile. The reload reads of one pair are
/// 4 ds_reads, so the next iteration's MFMA j needs only the reads of pair j: with the scoreboard wait pass the waits are partial (`lgkmcnt(12)`, `(8)`, `(4)`, `(0)`), not `lgkmcnt(0)`.
fn probe_agpr_reload4_kernel(name: &str, inplace: bool) -> Function {
    let (mut b, o, n, tid) = sched_begin(name);
    let c0 = b.c_i32(0);
    let c1 = b.c_i32(1);
    let c16 = b.c_i32(16);
    let c64 = b.c_i32(64);
    let c8192 = b.c_i32(8192);
    let c127 = b.c_i32(127);
    let mul = b.c_i32(0x01010101);
    let add = b.c_i32(0x04030201);
    let mask = b.c_i32(0x3f3f3f3f);
    let t1 = b.mul_i32(tid, mul);
    let t2 = b.add_i32(t1, add);
    let w = b.let_(Op::AndI32(Opnd::Val(t2), Opnd::Val(mask)));
    let w1 = b.add_i32(w, mul);
    let data0 = b.frag4(w, w, w, w);
    let data1 = b.frag4(w1, w1, w1, w1);
    let off = b.mul_i32(tid, c16);
    let off2 = b.add_i32(off, c8192);
    b.store_lds_b128(Opnd::Val(off), Opnd::Val(data0));
    b.store_lds_b128(Opnd::Val(off2), Opnd::Val(data1));
    b.wait_lds(0);
    b.barrier();
    b.wait_lds(0);
    let zero = b.frag_zero(DType::Frag4);
    let mut inits: Vec<(DType, Opnd)> = vec![(DType::I32, Opnd::Val(c0))];
    for _ in 0..4 {
        inits.push((DType::Frag4, Opnd::Val(zero)));
    }
    for j in 0..8 {
        let (lo, hi) = if j % 2 == 0 { (off, off2) } else { (off2, off) };
        let f = b.load_lds_b128x2(Opnd::Val(lo), Opnd::Val(hi));
        inits.push((DType::Frag8, Opnd::Val(f)));
    }
    let vars = b.begin_loop(&inits);
    let it = vars[0];
    let acc: Vec<VarId> = vars[1..5].to_vec();
    let av: Vec<VarId> = vars[5..9].to_vec();
    let bv: Vec<VarId> = vars[9..13].to_vec();
    if inplace {
        for v in acc.iter().chain(av.iter()).chain(bv.iter()) {
            b.pin_agpr(*v);
        }
    }
    let nxt = b.add_i32(it, c1);
    let par = b.let_(Op::AndI32(Opnd::Val(nxt), Opnd::Val(c1)));
    let r0 = b.mul_i32(par, c8192);
    let r1 = b.xor_i32(r0, c8192);
    let la = b.add_i32(off, r0);
    let lb = b.add_i32(off, r1);
    for j in 0..4 {
        b.var_mfma_scale16(acc[j], Opnd::Var(av[j]), Opnd::Var(bv[j]), c127, c127, 0, 0);
        let (x, y) = if j % 2 == 0 { (la, lb) } else { (lb, la) };
        if inplace {
            let na = b.load_lds_b128x2(Opnd::Val(x), Opnd::Val(y));
            b.set_var(av[j], na);
            let nb = b.load_lds_b128x2(Opnd::Val(y), Opnd::Val(x));
            b.set_var(bv[j], nb);
        } else {
            let a_lo = b.load_lds_b128(Opnd::Val(x));
            let a_hi = b.load_lds_b128(Opnd::Val(y));
            let na = b.cat_frag8(a_lo, a_hi);
            b.set_var(av[j], na);
            let b_lo = b.load_lds_b128(Opnd::Val(y));
            let b_hi = b.load_lds_b128(Opnd::Val(x));
            let nb = b.cat_frag8(b_lo, b_hi);
            b.set_var(bv[j], nb);
        }
    }
    sched_end_loop(&mut b, it, n);
    let row_off = b.mul_i32(tid, c64);
    let row = b.ptr_add(o, row_off);
    for (q, v) in acc.iter().enumerate() {
        for i in 0..4u8 {
            let l = b.frag4_lane(*v, i);
            let x = b.bitcast_f32(l);
            b.store_f32(row, 4 * (4 * q as u32 + i as u32), x);
        }
    }
    b.finish()
}

pub fn probe_agpr_reload4_ref() -> Function {
    probe_agpr_reload4_kernel("probe_agpr_reload4_ref", false)
}
pub fn probe_agpr_reload4() -> Function {
    probe_agpr_reload4_kernel("probe_agpr_reload4", true)
}

/// Regression probe for the silent miscompile found in the GEMM (docs/agpr.md "LDS spill + DMA operand wait"): the loop-invariant buffer voffset of an LDS-DMA load is spilled to LDS by the
/// register-pressure ladder (`AMDC_RA_LDS_SPILL=N AMDC_RA_LDS_SPILL_TARGET=0` forces it) and reloaded by a `ds_read` right before the DMA; the DMA must wait for that read.
/// Without the fix (`AMDC_WAITS_SKIP_FENCE_OPERANDS=1`) the wait is missing and the DMA reads a stale voffset. Output: per thread, n * (first dword of the 16 bytes it DMA-ed), identical
/// with and without the spill.
pub fn probe_dma_voff_spill() -> Function {
    let (mut b, o, n, tid) = sched_begin("probe_dma_voff_spill");
    let c0 = b.c_i32(0);
    let c1 = b.c_i32(1);
    let c16 = b.c_i32(16);
    let c63 = b.c_i32(63);
    let c1024 = b.c_i32(1024);
    let mul = b.c_i32(0x01010101);
    let add = b.c_i32(0x04030201);
    let o16 = b.mul_i32(tid, c16);
    let t1 = b.mul_i32(tid, mul);
    let t2 = b.add_i32(t1, add);
    let mask = b.c_i32(0x3f3f3f3f);
    let w = b.let_(Op::AndI32(Opnd::Val(t2), Opnd::Val(mask)));
    let data = b.frag4(w, w, w, w);
    // stage the input in the output buffer: out[tid*16 ..] = pattern(tid)
    let pin = b.ptr_add(o, o16);
    b.store_f32x4(pin, 0, data);
    b.wait_vm(0);
    let rin = b.buffer_rsrc(o);
    let c6 = b.c_i32(6);
    let wave = b.let_(Op::LshrI32(Opnd::Val(tid), Opnd::Val(c6)));
    let ldsb = b.mul_i32(wave, c1024);
    let lane = b.let_(Op::AndI32(Opnd::Val(tid), Opnd::Val(c63)));
    let lane16 = b.mul_i32(lane, c16);
    let rd = b.add_i32(ldsb, lane16);
    let vars = b.begin_loop(&[(DType::I32, Opnd::Val(c0)), (DType::I32, Opnd::Val(c0))]);
    let (it, acc) = (vars[0], vars[1]);
    b.buffer_load_lds_b128(rin, o16, c0, ldsb, 0); // descriptor base = o: the input staged in out[0 .. 16*tid) (overwritten by the result after the loop)
    b.wait_vm(0);
    let x = b.load_lds_b32(rd);
    let a2 = b.add_i32(acc, x);
    b.set_var(acc, a2);
    let _ = c1;
    sched_end_loop(&mut b, it, n);
    let c4 = b.c_i32(4);
    let off4 = b.mul_i32(tid, c4);
    let row = b.ptr_add(o, off4);
    let r = b.bitcast_f32(acc);
    b.store_f32(row, 0, r);
    b.finish()
}

/// Stamp probe (`FnBuilder::memtime_lo`): per wave record of 8 u32 in `out`: [t0, t1, t2, t3, x, 0, 0, 0] where t0..t3 are `s_memtime` low words taken around a dependent
/// VALU chain (t0 -> t1), back to back (t1 -> t2, the stamp cost itself) and around a scalar chain (t2 -> t3); x keeps the chains alive. Grid (n, 1, 1), block 256.
pub fn probe_stamp() -> Function {
    let mut b = FnBuilder::new("probe_stamp", 256);
    b.arg("out", DType::Ptr, 0, 8);
    let out = b.let_(Op::KernargPtr { offset: 0 });
    let bx = b.let_(Op::WorkgroupIdX);
    let tid = b.let_(Op::WorkitemId);
    let rec = b.stamp_rec_off(bx, 8, 4);
    let c3 = b.c_i32(3);
    let t0 = b.memtime_lo();
    let mut x = tid;
    for _ in 0..128 {
        x = b.add_i32(x, c3);
        x = b.let_(Op::XorI32(Opnd::Val(x), Opnd::Val(tid)));
    }
    let t1 = b.memtime_lo();
    let t2 = b.memtime_lo();
    let mut y = bx;
    for _ in 0..64 {
        y = b.mul_i32(y, c3);
    }
    let t3 = b.memtime_lo();
    b.stamp_store(out, rec, 0, t0);
    b.stamp_store(out, rec, 1, t1);
    b.stamp_store(out, rec, 2, t2);
    b.stamp_store(out, rec, 3, t3);
    b.stamp_store(out, rec, 4, x);
    b.stamp_store(out, rec, 5, y);
    b.finish()
}

/// Generic one-hot probe of `v_smfmac_f32_16x16x128_fp8_fp8` (docs/isa-probes-smfmac-tr.md): probe `bx` (one 64-lane wave per block) loads lane `l`'s A (4 dwords at
/// `a_in[(64 bx + l) * 16]`), B (8 dwords at `b_in[(64 bx + l) * 32]`) and SRC2 index dword (`i_in[(64 bx + l) * 4]`) straight from global memory, issues ONE
/// smfmac with a zero accumulator and stores D (4 dwords per lane) to `d_out[(64 bx + l) * 16]`. The host chooses every register bit.
pub fn probe_smfmac_gen() -> Function {
    let mut b = FnBuilder::new("probe_smfmac_gen", 64);
    b.arg("a_in", DType::Ptr, 0, 8);
    b.arg("b_in", DType::Ptr, 8, 8);
    b.arg("i_in", DType::Ptr, 16, 8);
    b.arg("d_out", DType::Ptr, 24, 8);
    let a_in = b.let_(Op::KernargPtr { offset: 0 });
    let b_in = b.let_(Op::KernargPtr { offset: 8 });
    let i_in = b.let_(Op::KernargPtr { offset: 16 });
    let d_out = b.let_(Op::KernargPtr { offset: 24 });
    let bx = b.let_(Op::WorkgroupIdX);
    let tid = b.let_(Op::WorkitemId);
    let c64 = b.c_i32(64);
    let base = b.mul_i32(bx, c64);
    let g = b.add_i32(base, tid);
    let c4 = b.c_i32(4);
    let c16 = b.c_i32(16);
    let c32 = b.c_i32(32);
    let ao = b.mul_i32(g, c16);
    let bo = b.mul_i32(g, c32);
    let io = b.mul_i32(g, c4);
    let ap = b.ptr_add(a_in, ao);
    let bp = b.ptr_add(b_in, bo);
    let ip = b.ptr_add(i_in, io);
    let dp = b.ptr_add(d_out, ao);
    let mut aw = Vec::new();
    for i in 0..4u32 {
        let f = b.load_f32(ap, 4 * i);
        aw.push(b.bitcast_i32(f));
    }
    let mut bw = Vec::new();
    for i in 0..8u32 {
        let f = b.load_f32(bp, 4 * i);
        bw.push(b.bitcast_i32(f));
    }
    let fi = b.load_f32(ip, 0);
    let idx = b.bitcast_i32(fi);
    let a = b.frag4(aw[0], aw[1], aw[2], aw[3]);
    let bb = b.frag8(bw[0], bw[1], bw[2], bw[3], bw[4], bw[5], bw[6], bw[7]);
    let c0 = b.frag_zero(DType::Frag4);
    let d = b.smfmac_fp8_16x16x128(a, bb, idx, c0);
    b.store_f32x4(dp, 0, d);
    b.finish()
}

/// Generic probe of `ds_read_b64_tr_b8`: lane `l` of probe `bx` reads LDS byte address `addr_in[64 bx + l]` (the LDS holds the 4096 bytes of `src`, copied in by the
/// kernel) and stores the two result dwords to `d_out[(64 bx + l) * 8]`.
pub fn probe_lds_tr_b8_gen() -> Function {
    let mut b = FnBuilder::new("probe_lds_tr_b8_gen", 64);
    b.lds(4096);
    b.arg("src", DType::Ptr, 0, 8);
    b.arg("addr_in", DType::Ptr, 8, 8);
    b.arg("d_out", DType::Ptr, 16, 8);
    let src = b.let_(Op::KernargPtr { offset: 0 });
    let addr_in = b.let_(Op::KernargPtr { offset: 8 });
    let d_out = b.let_(Op::KernargPtr { offset: 16 });
    let bx = b.let_(Op::WorkgroupIdX);
    let tid = b.let_(Op::WorkitemId);
    let c2 = b.c_i32(2);
    let c3 = b.c_i32(3);
    let c64 = b.c_i32(64);
    // copy the 4096 source bytes into LDS: lane l writes dwords l + 64 k, k = 0..15
    for k in 0..16i32 {
        let ck = b.c_i32(64 * k);
        let dw = b.add_i32(tid, ck);
        let off = b.shl_i32(dw, c2);
        let p = b.ptr_add(src, off);
        let f = b.load_f32(p, 0);
        let w = b.bitcast_i32(f);
        b.store_lds_b32(Opnd::Val(off), Opnd::Val(w));
    }
    b.wait_lds(0);
    b.barrier();
    b.wait_lds(0);
    let base = b.mul_i32(bx, c64);
    let g = b.add_i32(base, tid);
    let ao = b.shl_i32(g, c2);
    let ap = b.ptr_add(addr_in, ao);
    let fa = b.load_f32(ap, 0);
    let addr = b.bitcast_i32(fa);
    let r = b.load_lds_tr_b8(Opnd::Val(addr));
    b.wait_lds(0);
    let oo = b.shl_i32(g, c3);
    let dp = b.ptr_add(d_out, oo);
    for i in 0..2u8 {
        let lane = b.frag16_lane(r, i);
        let v = b.bitcast_f32(lane);
        b.store_f32(dp, 4 * i as u32, v);
    }
    b.finish()
}
